SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for artifact
-- ----------------------------
DROP TABLE IF EXISTS `artifact`;
CREATE TABLE `artifact`  (
  `artifact_id` bigint NOT NULL AUTO_INCREMENT COMMENT '文物ID',
  `artifact_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文物名称',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '佚名' COMMENT '作者/匠人',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类别(如：瓷器、书画、青铜器)',
  `dynasty` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '朝代',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文物详细描述',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主图URL',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态: 0-馆藏中, 1-外借巡展中, 2-维修保养中',
  `storage_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存放位置',
  `owner_museum` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属博物馆',
  `current_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前所在地(若为空则表示在原馆)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '录入时间',
  PRIMARY KEY (`artifact_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 229 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文物信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of artifact
-- ----------------------------
INSERT INTO `artifact` VALUES (1, '青花瓷瓶', '佚名', '瓷器', '元代', '白釉青花点笔浓，冰肌玉骨自沉香。\n\n作为中国瓷器史上最耀眼的符号，青花瓷瓶，用最纯粹的两种色彩，勾勒出了东方美学的最高境界。\n\n从工艺科普的视角来看，它是极为经典的釉下彩传奇。匠人们用含氧化钴的苏麻离青等天然钴料，在素白的泥胎上纵笔挥洒，随后罩上一层透明釉，经1300度的高温一次烧成。那晕染开来的蓝色，深沉时如墨落幽潭，翠透时如雨后初晴。更因其独特的烧制工艺，使得发色永不褪色，真正实现了“白青相映，历久弥新”。\n\n它的美，在于**“繁花落尽见真淳”**。瓶身之上，无论是缠枝牡丹的富贵，还是山水人物的隐逸，都被过滤成了素雅的蓝与白。\n\n抚摸着细腻如玉的瓶身，如同抚摸一段被烈火凝固的河流。青花瓷瓶不仅是一件盛装岁月的雅器，更是一首用泥土与火写就的视觉诗篇，惊艳了时光，也温柔了惊鸿。', 'http://localhost:8080/files/e0d5675c-c8e2-47eb-80cb-22d4875def42.png', 1, 'C栋一层展厅214', '河北博物馆', '河北博物馆', '2026-02-23 15:15:01');
INSERT INTO `artifact` VALUES (3, '烟雨瓷瓶', '佚名', '瓷器', '元代', '烟雨瓷瓶，是一场将江南春汛定格于泥土与烈火中的浪漫视觉。\n\n从工艺上看，它多采用天青或粉青釉色为底，运用独特的窑变、泼墨分水或晕染技法。在近千度的高温淬炼下，釉料在胎体上自然流动、晕散，如同水墨入水，幻化出如丝如缕的朦胧雾气与层层叠叠的远山暮色。出窑那一刻，原本冰冷坚硬的瓷器，竟有了烟雨江南“山色空蒙雨亦奇”的流动感。\n\n它的美，在于“虚实相生”。不着一字，不见一滴雨，却凭借釉色的浓淡交织，让人仿佛能听见雨打芭蕉的清脆，看见乌篷船划破波光的微澜。\n\n展卷迎风，一瓶在侧。它不仅是一件装点空间的雅器，更是一扇开在凡尘中的窗——无需舟车劳顿，只要凝眸于这青白交织的釉面，心便已宿在了那浸润了千年的烟雨江南里。', 'http://localhost:8080/files/1fca5e11-4ff7-4d3c-b509-f25f1ed51037.png', 0, '1库房', '河北博物馆', '1库房', '2026-02-23 15:17:00');
INSERT INTO `artifact` VALUES (4, '千里江山图（摹本）', '王希孟', '绘画', '北宋', '天才少年一跃千年，青绿山水冠绝华夏。\n\n这是北宋十八岁少年王希孟，留在人间唯一的绝响——《千里江山图》。\n\n在纵11.9米的浩瀚长卷中，少年以惊世之才，科普了中国传统绘画中**“大青绿山水”的极致美学。他用珍贵的孔雀石**研磨成青，蓝铜矿提炼成绿，再辅以赭石与金粉，在绢本上层层敷色。历经千载，那抹青绿非但没有黯淡，反而愈发璀璨夺目。画面中烟波浩渺、层峦叠嶂，渔村野市、水榭亭台错落其间，将千里江山的雄浑与江南水乡的柔美完美融为一体。\n\n它的伟大，不仅在于“咫尺有千里之趣”的宏大构图，更在于那抹永不褪色的青绿背后，所燃烧的少年热血与大宋盛世的浩荡风华。\n\n展卷那一刻，千山激荡，万水奔流。这不仅是一幅画作，更是中华民族对大好河山最深情、最壮丽的视觉图腾。', 'http://localhost:8080/files/e7ff4d7f-d041-4a5c-9ece-e92ed8127f01.png', 0, '1库房', '河北博物馆', '1库房', '2026-02-23 15:17:00');
INSERT INTO `artifact` VALUES (6, '唐三彩贴花马', '佚名', '瓷器', '唐代', '大唐风骨跃泥胎，极彩流光自盛世。\n\n这是一匹从一千多年前的长安城中，迎着驼铃与西风，长啸而来的大唐骏马。\n\n从工艺科普的视角来看，唐三彩并非只有三种颜色，而是一种低温铅釉陶器。它以高岭土为胎，用含铜、铁、锰等元素的矿物做着色剂，在800度左右的窑火中烧制。最绝妙的是它的“流釉”工艺——在高温下，黄、绿、白（或褐、蓝）等各色釉料自然熔融、交织流淌，形成了斑斓绚丽、变幻莫测的斑驳色彩，每一匹都独一无二。\n\n画面中的三彩马，骨骼健壮，肌肉丰满，双耳如裁竹，双眸炯炯有神，那一低头或一扬蹄的姿态，将西域汗血宝马的雄浑野性与大唐匠人炉火纯青的雕塑功底展现得淋漓尽致。\n\n它身上的斑斓釉色，不仅是泥与火的艺术，更是那个包容万国、自信张扬的盛唐气象，在时光深处留下的最绚丽、最骄傲的侧影。', 'http://localhost:8080/files/2875158f-17e6-4eb5-ae4d-c14f84411354.png', 0, '3库房', '河北博物馆', '河北博物馆', NULL);
INSERT INTO `artifact` VALUES (102, '后母戊鼎', '佚名', '青铜', '商代', '国之重器，礼乐之尊。\n作为现存商代青铜文化鼎盛时期的至高杰作，后母戊鼎以其雄浑磅礴的体量，被誉为“镇国之宝”。\n它历经三千余年风霜，鼎身盘踞着神秘威严的饕餮纹与夔龙纹，彰显着殷商王室祭祀天地、沟通神明的至高威权。四足定乾坤，双耳承天命。翻开这部沉重的青铜史诗，抚摸那斑驳的铜绿，我们触碰到的不仅是商代匠人炉火纯青的铸造奇迹，更是中华文明绵延不绝、厚重如山的文化根基。', 'http://localhost:8080/files/16b65d0a-d0a4-4110-94df-824c391b72cd.png', 1, '珍宝馆A区', '广东省博物馆', '河北博物馆东馆二楼', '2026-04-12 21:07:14');
INSERT INTO `artifact` VALUES (103, '汝窑天青釉洗', '佚名', '瓷器', '北宋', '汝窑天青釉洗，承载了宋徽宗梦境中最极致的中式美学。\n釉如凝脂，天青犹翠；器形大巧若拙，简素明净。抚之如绢，望之如玉。\n那细密莹澈的蝉翼纹开片，是时光在素肌上留下的诗意痕迹；底部的芝麻细小支钉，更是巧夺天工的传世印证。它不事雕琢，却以一抹似蓝非蓝、似绿非绿的天青，将千年前宋人的禅意哲思与极简美学，定格为万古不朽的传奇。', 'http://localhost:8080/files/85ef3b7e-c287-4c99-b9c7-d8299fee8fc7.png', 0, '陶瓷馆', '广东省博物馆', '陶瓷馆', '2026-04-12 21:07:14');
INSERT INTO `artifact` VALUES (104, '兰亭集序(神龙本)', '王羲之', '法书', '东晋', '羲之真迹已随昭陵长眠，唯有“神龙本”《兰亭集序》，让那场永和九年的暮春修禊，在纸墨间活了千载。\n它承载着大唐宫廷的最高机密，双钩填墨，细若游丝。\n翻开此卷，王羲之微醺时的遒媚飘逸跃然纸上：二十一个“之”字字字不同，如流云、如惊鸿、如惊雷。由于采用了破锋双钩，我们甚至能顺着那若隐若现的牵丝映带，触碰到冯承素等大唐摹工指尖的呼吸，看见千年前魏晋名士一觞一咏的狂放与悲悯。这不仅是一张摹本，它是唯一能让我们无限逼近王羲之灵魂的旷世神作。', 'http://localhost:8080/files/293bada6-c60e-44ba-b138-e11b543121e7.png', 1, '三号库房', '广东省博物馆', '广东博物馆A馆', '2026-04-12 21:07:14');
INSERT INTO `artifact` VALUES (105, '金缕玉衣', '佚名', '玉石器', '西汉', '金缕交织千秋梦，玉衣空锁万古魂。\n\n这是一件用生死执念编织而成的时光战甲——西汉金缕玉衣。\n\n从科普的微观视角来看，它是中国汉代顶级规格的丧葬礼服。整件玉衣由数千块天然和田玉片精雕细琢而成，四角钻孔，以纯金细丝（金缕）抽丝编缀，严丝合缝地包裹住逝者的躯体。在汉人“金玉在九窍，则死者为之不朽”的朴素哲学里，玉石承载着灵魂不灭、羽化登仙的期冀。\n\n然而，历史给出了最冷峻的回答：纵使金缕坚韧、美玉无瑕，内里的血肉之躯终究化作了历史的尘埃，唯留这件冰冷而绚烂的玉衣，独自在黑暗的墓室中对抗了千年的孤寂。\n\n抚摸这冰凉的玉面，我们看到的不仅是汉代手工业巅峰时期的惊世奇迹，更是一篇用金与玉写就的、关于人类对抗死亡与时间的浪漫史诗。', 'http://localhost:8080/files/2f9e6547-82cc-487b-8464-e0c6583ee41d.png', 0, '出土文物厅', '广东省博物馆', '河北省博物馆A栋文化展厅', '2026-04-12 21:07:14');
INSERT INTO `artifact` VALUES (130, '黑白画像', '赵晓璇', '绘画', '现代', '岁月入墨，风霜满面；寥寥数笔，尽得风流。\n\n这是一幅承载着东方生命智慧与岁月沉淀的古风水墨老人画像。\n\n从中国传统绘画的科普视角来看，这幅画作将水墨写意（或兼工带写）的技法发挥到了极致。艺术家摒弃了五彩斑斓的颜色，仅凭借“墨分五色”（浓、淡、焦、干、湿）的精妙变化，在宣纸上晕染出老人的神韵。干笔皴擦出额头如刀刻般的皱纹，那是岁月留下的年轮；浓墨点染出沉静如海的眼眸，那是洞察世事后的通透；而衣褶处的泼墨留白，则深得传统美学“计白当黑”的禅意，虚实相生，气韵生动。\n\n画中的老人，或许是隐逸山林的智者，又或许是历尽沧桑的农夫。他无需言语，那微微颔首的姿态、饱经风霜的轮廓，本身就是一部活着的历史。\n\n这不仅是一幅画像，更是一首无声的生命赞歌。水墨在宣纸上洇散的过程，正如光阴在生命里留下的痕迹——虽无声色犬马的喧嚣，却有着独属于东方的、厚重而高贵的纯粹。', 'http://localhost:8080/files/faa83d6c-65e7-4f39-b288-30a6912c04be.png', 0, '现代艺术馆B区', '河北博物馆', '现代艺术馆B区', NULL);
INSERT INTO `artifact` VALUES (131, '五四青年画卷', '张智广', '绘画', '现代', '百年风雷激荡，青春破浪迎来。\n\n这是一幅用现代艺术语言，重塑热血灵魂与觉醒年代的《五四青年画卷》。\n\n从现代绘画艺术的科普视角来看，这幅作品打破了传统历史画作的沉闷，巧妙融合了表现主义的强烈色彩与现代构成感的线条。画面多采用象征觉醒与激情的红、象征真理与希望的蓝，形成高饱合度的视觉对撞。画中青年的面部轮廓运用了硬朗、果断的现代几何切面设计，眼神坚毅，姿态昂扬。这种“写意与具象”的交织，不仅精准捕捉了百年前青年们“以青春之我，创建青春之国家”的无畏气魄，更赋予了画面极强的现代张力和时代感。\n\n长卷铺展，不是历史的简单复刻，而是青春精神的隔空共振。\n\n凝视这幅画卷，那挥舞的旗帜、呐喊的群像，仿佛化作了冲破黑暗的炽热火炬。它用最现代的笔触，向所有观者宣告：五四不是一个完成时，而是一个进行时——只要热血未冷，理想犹在，青年的脊梁，便永远是这个时代最壮丽的风景。', 'http://localhost:8080/files/097aa957-d678-46a8-b427-0a513107512e.png', 0, 'B馆', '广东省博物馆', 'B馆', NULL);
INSERT INTO `artifact` VALUES (133, '松风阁（摹本）', '黄庭坚', '法书', '北宋', '一笔松风拂旷野，千年铁骨驻人间。\n\n作为“宋四家”之一黄庭坚晚年的绝对代表作，《松风阁诗帖》（摹本）以其苍劲孤傲的笔墨，定格了中国书法史上最惊心动魄的文人风骨。\n\n从书法与复制工艺的科普视角来看，此摹本精确还原了黄庭坚独创的“长笔辐射”与“战笔”特征。字形中宫紧收，四周笔画如长枪大戟般极力向外伸展，纵横跌宕；在书写横画、直画时，线条伴随着特有的颤动（战笔），如同苍松在疾风中抗争的枝干。通过精细的现代或传统摹刻工艺，墨色的枯润燥湿、运笔的提按顿挫被纤毫毕现地保留下来，达到了“下真迹一等”的艺术效果。\n\n诗中所写的“松风阁”，不仅是依山而建的避暑之所，更是黄庭坚在命运沉浮中，聆听松涛、叩问生命的栖息地。\n\n虽然真迹远在天涯，但展读这卷摹本，那如长松傲雪的线条、如万壑松风的笔势依然扑面而来。它不仅是一门技艺的传承，更是每一位观者穿越时空，与那位倔强、高傲的宋代灵魂最深情的相遇。', 'http://localhost:8080/files/3df4340e-58b3-4680-ac86-d4c99099a0ff.png', 1, 'C库房2-1区', '上海博物馆', '广东博物馆A馆', NULL);
INSERT INTO `artifact` VALUES (134, '歌乐图卷', '佚名', '绘画', '南宋', 'http://googleusercontent.com/image_collection/image_retrieval/13926615024765792976_0为您奉上一段针对上海博物馆藏南宋佚名《歌乐图卷》的专属介绍词，融入了南宋特有的精致审美、服饰乐器科普与历史文化内涵：\n\n泥金褙子衬罗裙，八百年遥听宋音。\n\n这是一幅深藏于上海博物馆的南宋传世孤品——《歌乐图卷》，它将南宋宫廷教坊乐班排练演奏的唯美瞬间，定格在盈尺绢素之间。\n\n从历史与服饰乐器的科普视角来看，此卷堪称南宋社会文化生活的生动写照。全卷在背景上极简留白，仅以太湖石、廊栏和棕榈树营造出清幽的庭院。苑中十二位人物一字排开，其中九位南宋教坊女伎身姿修长，统一穿着当时最时髦的红色窄袖褙子，衣襟上绘有象征官方尊贵身份的泥金图案；她们头梳高髻，簪以独特的珠翠“团冠”。乐班手中所持的曲项琵琶、拍板、方响、排箫等乐器组合，严谨地复刻了宋代教坊的演乐制式。\n\n它的珍贵，在于“以画证史”。两宋时期瓦舍勾栏、听戏看曲之风盛行，但在传世南宋人物画中，唯独此卷以极其罕见的写实笔触，聚焦于歌乐女伎这一题材。\n\n展开这幅设色艳丽、用笔精细的画卷，那流畅的衣纹与专注的乐手交织。没有宏大的战争叙事，只有市井或宫廷深处最优雅的丝竹余音。它用这一抹流传了八百年的中国红，带我们重温了那个清雅、内敛却又极具审美张力的两宋时代。', 'http://localhost:8080/files/b5207eed-28c9-4d20-938c-8ef241d5aa1d.jpg', 0, '书画展厅', '上海博物馆', '书画展厅', NULL);
INSERT INTO `artifact` VALUES (135, '千字文卷', '赵佶', '法书', '北宋', '为您奉上一段兼具帝王才情、瘦金体书法科普、极致视觉美学与历史宿命感的赵佶（宋徽宗）《草书千字文》或《瘦金体千字文》介绍词（这里以他最震撼、最惊世骇俗的《草书千字文》为例，若您需要瘦金体版可随时告诉我）：\n\n狂草狂飙惊风雨，一笔写尽帝王孤。\n\n这是北宋艺术之王宋徽宗赵佶，在宣和四年写下的旷世神作——《草书千字文》。\n\n从书法工艺的科普视角来看，这幅长达十数米的巨幅长卷，堪称中国书法史上的炫技之作。赵佶打破了他标志性“瘦金体”的严谨规整，以极具爆发力的狂草一气呵成。笔势如惊雷奔马、飞瀑落九天，线条看似细若游丝，实则铁画银钩，内含惊人的风骨与劲道。更令人叹为观止的是它的载体——这是一张由宫廷特制的、长达十一米多且毫无拼接痕迹的“巨幅防风盐水笺”。画师在纸上用泥金描绘出暗隐的飞龙图案，赵佶在金龙墨海间挥洒纵横，真正做到了“字字腾飞，龙蛇游走”。\n\n它的震撼，在于“诸美共流”的极致浪漫。一千个字，无一字懈怠，无一笔重样。\n\n凝视这幅长卷，金色的龙纹在墨色下若隐若现，狂放的草书在纸上呼啸而过。这不仅是一场笔墨的狂欢，更是这位文艺帝王在北宋大厦将倾前，倾尽全国之力，用天才的灵感和最奢华的材质，为那个崇尚极致美学的时代写下的一首绚丽、决绝的告别诗。', 'http://localhost:8080/files/845a6813-8965-467b-8196-a938bd901290.jpg', 1, '东馆法书展厅', '上海博物馆', '广东博物馆A馆', NULL);
INSERT INTO `artifact` VALUES (136, '春秋楚王孙铜钟', '佚名', '青铜', '春秋', '铸于春秋时期，通高58.9厘米。主体呈合瓦形，器体下边为弧形。隧与鼓部饰有精美的蟠螭纹，篆、甬、舞部均饰窃曲纹。此钟最珍贵之处在于其钲部与左右鼓部皆刻有铭文，正背共六处，总计48字，记载了楚王孙的相关事迹，具有极高的历史研究与文字考证价值。', 'http://localhost:8080/files/53fcda69-8d69-4cc5-ad6a-46f09d4dbbbb.png', 1, '历史展厅/青铜器专柜', '广东省博物馆', '河北博物馆东馆二楼', '2026-05-25 18:20:42');
INSERT INTO `artifact` VALUES (137, '战国翼兽形铜盉', '佚名', '青铜', '战国', '战国时期的调酒或盛水器。该器物造型奇特且充满想象力，整体呈一只带有双翼的异兽形状。器身线条流畅，纹饰繁缛细腻，融实用性与高超的青铜造型艺术于一体，是反映战国时期青铜铸造工艺巅峰的代表作之一。', 'http://localhost:8080/files/94fe2e5c-c0dc-40f4-9401-3440b0a2335c.png', 1, '古代铜器展厅', '广东省博物馆', '河北博物馆东馆二楼', '2026-05-25 18:20:42');
INSERT INTO `artifact` VALUES (138, '东汉冷水冲型变形羽人纹四蛙乘骑像铜鼓', '佚名', '青铜', '东汉', '出土于两广地区，属于北方冷水冲型铜鼓。鼓面中心装饰有醒目的太阳纹，四周及鼓身布满变形羽人纹等细密纹饰。最核心的特征是鼓面边缘铸有四只栩栩如生的青蛙以及乘骑人物塑像，体现了岭南古代先民（西瓯、俚人等）的图腾崇拜、祭祀礼仪以及独特的稻作文化。', 'http://localhost:8080/files/90738a68-e426-416e-8747-f8d615123807.png', 1, '岭南历史与文化展厅', '广东省博物馆', '河北博物馆东馆二楼', '2026-05-25 18:20:42');
INSERT INTO `artifact` VALUES (139, '东周青铜人首柱形器', '佚名', '青铜', '东周', '广东本地考古发掘的代表性青铜器，多流行于粤北、粤东等地的先秦墓葬中。器物顶端铸有人首形状，面部特征带有浓郁的岭南土著民族（百越民族）的相貌特征。此类器物通常在底部设有插栓，是研究先秦时期岭南古国（如西瓯、南越前身）社会形态、兵器装备和族群面貌的独家物证。', 'http://localhost:8080/files/2854cbc1-2f3b-4e94-8b13-caf70139cd3b.png', 1, '岭南考古展厅', '广东省博物馆', '河北博物馆东馆二楼', '2026-05-25 18:20:42');
INSERT INTO `artifact` VALUES (140, '南宋陈容墨龙图轴', '陈容', '绘画', '南宋', '国家一级文物，是南宋画龙名家陈容传世的经典神作。画面中一条巨龙在狂风乌云、惊涛骇浪中破空而出，龙首威严，龙爪凌厉。全画纯用墨色，将水墨的浓淡干湿发挥到了极致，展现了极强的视觉冲击力与文人写意精神，历经近千年流传至今，弥足珍贵。', 'http://localhost:8080/files/8a117542-92e2-4f58-b66e-e70965df1cb8.png', 0, '历代绘画展厅/1号专柜', '广东省博物馆', NULL, '2026-05-25 18:22:27');
INSERT INTO `artifact` VALUES (141, '明颜宗湖山平远图卷', '颜宗', '绘画', '明代', '国家一级文物，被誉为“目前所见存世最早的广东本地画迹”。此画作于明正统时期，采用传统的三段式和平远构图，描绘了南方水乡山峦起伏、平沙万里、秋水浩渺的恬静风光。该作打破了岭南古代无大家画迹传世的记录，在中国绘画史和广东美术史上具有里程碑意义。', 'http://localhost:8080/files/7dfdfbbf-8468-48d6-bc27-ee5d51aedce1.png', 0, '广东历代绘画展厅', '广东省博物馆', NULL, '2026-05-25 18:22:27');
INSERT INTO `artifact` VALUES (142, '北宋无款群峰晴雪图轴', '佚名', '绘画', '北宋', '这是广东省博物馆馆藏绘画中时代最早的一幅艺术珍品。作品虽然没有作者落款，但深得北宋山水画“高远”与“深远”的精髓。画面描绘了冬日雪后群山初晴的宏伟景象，山石皴法严谨，气势雄浑，完美体现了北宋时期全景式山水画的崇高与静谧之美。', 'http://localhost:8080/files/15ee8aab-797a-4df4-b7f6-ad0d8169713d.png', 0, '宋元书画特展区', '广东省博物馆', NULL, '2026-05-25 18:22:27');
INSERT INTO `artifact` VALUES (143, '宋青白釉暗花缠枝牡丹纹大碗', '佚名', '瓷器', '宋代', '景德镇窑青白瓷的代表作。大碗造型端庄，胎质洁白细腻，釉色介于青白之间，莹润如玉。碗内壁刻划有流畅的缠枝牡丹纹饰，线条生动，深浅有致。在温润釉色的衬托下，若隐若现，尽显宋代素雅、内敛的极简美学。', 'http://localhost:8080/files/fdc8aa4f-3f50-4ad6-9b05-c7084cc41b12.png', 0, '历代陶瓷展厅/宋代瓷器区', '广东省博物馆', NULL, '2026-05-25 18:23:31');
INSERT INTO `artifact` VALUES (144, '清康熙青花大件山水人物纹瓷盘', '佚名', '瓷器', '清康熙', '清代康熙时期青花瓷的精品之作。此时期的青花以“墨分五色”著称，绘画工艺极高。盘面通过深浅不同的青色，勾勒出层峦叠嶂的山水景致与栩栩如生的人物故事，宛如一幅水墨山水画绢本平铺在瓷器之上，极具艺术观赏价值。', 'http://localhost:8080/files/e62b4a4b-86d2-4d45-b2ca-60e50afd7e99.png', 0, '明清陶瓷专展区', '广东省博物馆', NULL, '2026-05-25 18:23:31');
INSERT INTO `artifact` VALUES (145, '清乾隆广彩外销西洋人物图盘', '佚名', '瓷器', '清乾隆', '极具岭南本土与海上丝绸之路特色的“广彩”（广州织金彩瓷）外销瓷。瓷盘由景德镇烧制白胎，运至广州进行加彩烘烧。盘心绘有典型的西洋人物、庭院景观，四周饰以繁复的织金花卉纹。该器物是清代“一口通商”时期中西文化交融、贸易往来的重要实物见证。', 'http://localhost:8080/files/b3145775-75c9-4099-8b8c-8fd1a2a41abd.png', 0, '海上丝绸之路与外销瓷展厅', '广东省博物馆', NULL, '2026-05-25 18:23:31');
INSERT INTO `artifact` VALUES (146, '明万历青花象首耳大瓶', '佚名', '瓷器', '明代', '明代万历时期的典型大件陈设瓷。器形宏大，颈部两侧对称饰以象首形耳，寓意“太平有象”。瓶身通体以回青料描绘缠枝莲纹及吉祥图案，发色浓艳泛紫。由于晚明时期大件瓷器极易在窑中变形，此类保存完好且成色上佳的大瓶非常难得。', 'http://localhost:8080/files/cd1f6ae2-e3a2-4bc8-b3b5-df4f67ba5897.png', 0, '历代陶瓷展厅/明代瓷器区', '广东省博物馆', NULL, '2026-05-25 18:23:31');
INSERT INTO `artifact` VALUES (147, '西汉透雕龙凤纹重环玉佩', '佚名', '玉石器', '西汉', '出土于广州南越王墓，是南越国玉雕工艺的巅峰之作。玉佩分内外两重环，内环透雕一条游龙，外环透雕一只凤鸟，龙凤顾盼生姿。此器构图完美平衡，线条充满动感，是汉代玉器中不可多得的国宝级珍品。', 'http://localhost:8080/files/6691bde5-8626-4cc2-94c0-343d3ce447e3.png', 0, '历代玉器展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (148, '清端石千岩竞秀砚', '佚名', '玉石器', '清代', '作为广东特产的“端砚”居中国四大名砚之首。此砚采用名贵的端州老坑石精雕而成，石质细腻如玉。砚身巧妙利用石眼与瑕疵，因材施艺，雕刻出千岩竞秀、层峦叠嶂的壮丽山水奇景，是文房雅玩中的极品。', 'http://localhost:8080/files/c699f2a6-88d4-4393-b326-799a722c6b60.png', 1, '广东端砚工艺特展区', '广东省博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (149, '良渚文化玉璧', '佚名', '玉石器', '新石器时代', '征集自新石器时代良渚文化核心区域。玉璧呈暗绿色，质地厚重，中心对钻圆孔。表面保留了原始打磨的痕迹，素面无纹。作为古代祭天重器，它是研究我国史前玉文化与早期礼制社会的重要实物。', 'http://localhost:8080/files/d7b00a1c-33b0-4abe-ad0e-90cac237f886.png', 0, '古代玉器陈列室', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (150, '明代玉雕花鸟纹执壶', '佚名', '玉石器', '明代', '由上等和田白玉雕琢而成，壶身线条流畅。外壁采用浅浮雕工艺刻画江南花鸟图案，工艺细腻。明代玉器讲究“粗大明”，但此件器物却呈现出少有的规整与雅致，反映了明代中后期文人审美的流行。', 'http://localhost:8080/files/4ac4faf4-850f-4907-a090-f6e7b4b5830f.png', 0, '历代玉器展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (151, '清代广绣百鸟朝凤图挂幅', '佚名', '织绣', '清代', '中国四大名绣之一“广绣”的传世佳作。画面以凤凰为中心，周边环绕着仙鹤、孔雀、鸳鸯等上百只形态各异的鸟类。广绣色彩浓艳、构图繁密，大量使用金银线刺绣，具有极强的立体感和极高的民间工艺价值。', 'http://localhost:8080/files/e6b266af-9e69-4723-b979-656eb1fdf9b8.png', 0, '岭南织绣与服饰展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (152, '明红地织金团花缎女褂', '佚名', '织绣', '明代', '明代高等级贵族妇女的节日盛装。以大红织金缎为面料，通体织有规整的团花图案。金线在红缎的衬托下熠熠生辉。由于丝织品极难保存，这件明代服饰至今仍色彩鲜艳、结构完整，在纺织史研究中极为罕见。', 'http://localhost:8080/files/9a77c2cc-391f-4c08-9d89-de252524d381.png', 2, '历代丝织品特藏库', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (153, '清潮绣金绒米白缎抽纱台布', '佚名', '织绣', '清末民初', '此件作品融合了潮绣（粤绣分支）的垫高绣技法与近代西方传入的抽纱工艺。图案多为岭南佳果与西洋花卉，中西合璧，具有鲜明的地方特色，是晚清时期广东外销织绣品畅销海内外的真实写照。', 'http://localhost:8080/files/32df4c13-ed01-4a3a-9ccb-a4aebb03d342.png', 0, '外销艺术品展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (154, '明黄缎地刺绣花卉纹幔帐', '佚名', '织绣', '明代', '高档宫廷或大户人家床榻、厅堂使用的幔帐。黄缎底色高贵，采用丝线绣出四季花卉及蝴蝶，寓意“耋耄富贵”。针法灵活多变，线条流畅，展现了明代刺绣工艺的婉约与大气。', 'http://localhost:8080/files/f9e33535-e420-46f6-90f2-321e5c3bf158.png', 0, '岭南织绣与服饰展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (155, '清乾隆铜胎画珐琅西洋人物双耳瓶', '佚名', '珐琅器', '清乾隆', '典型的“广珐琅”（广州制造的画珐琅精品）。该瓶在铜胎上敷白珐琅釉，再用色彩艳丽的珐琅料绘制西洋母子及乡村风景画，配以细致的缠枝花卉边饰。它是清代宫廷御用及外销的高级奢侈品。', 'http://localhost:8080/files/1dddd5c1-2258-4d98-8607-bd06ab26e99b.png', 0, '广珐琅特展区', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (156, '清中期掐丝珐琅缠枝莲纹出戟鼎', '内务府造办处', '珐琅器', '清中期', '北京宫廷造办处风格的“景泰蓝”重器。仿商周青铜鼎造型，四足出戟。通体以蓝色珐琅釉为地，填烧红、黄、绿、白等色珐琅料的缠枝莲纹。釉面光亮，镀金厚重，彰显了皇家的大气与威严。', 'http://localhost:8080/files/b6c5b04d-abc0-480c-8423-17afc782543b.png', 0, '明清工艺珍宝展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (157, '清晚期錾胎珐琅八宝纹花盆', '佚名', '珐琅器', '清晚期', '采用复杂的錾胎珐琅工艺制作。先在厚铜胎上錾刻出佛教“八宝”图案的轮廓，然后在下凹处填施各色珐琅釉料，经烧制、磨光、镀金而成。纹饰线条粗犷有力，具有极强的立体效果。', 'http://localhost:8080/files/9d010e5b-e9b0-4056-9067-235818334253.png', 0, '明清工艺珍宝展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (158, '清金漆木雕人物故事神龛', '佚名', '漆器', '清代', '国家一级文物，广东最具代表性的民间漆艺“潮州金漆木雕”的绝世之作。神龛通体黑漆垫底，运用通雕、浮雕等手法雕刻出密不透风的戏剧人物故事，最后通体贴金。金碧辉煌，繁复至极，将木雕与漆艺完美融合。', 'http://localhost:8080/files/3d5e820b-8e5d-4531-9eb5-33de6e959da3.png', 0, '广东潮州木雕展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (159, '清剔红海马呛水纹多宝盒', '佚名', '漆器', '清代', '精美的雕漆（剔红）工艺品。在木胎上层层髹涂红漆达几十层甚至上百层，再在半干的漆层上雕刻出汹涌的波涛与飞奔的海马。漆色鲜红夺目，刀法圆润，线条极具力度感。', 'http://localhost:8080/files/c6388b31-7ba0-4cf4-86cf-f6df3a9b394b.png', 0, '明清漆器陈列区', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (160, '清黑漆描金山水故事图八方牌盒', '佚名', '漆器', '清代', '专为西方市场定制的外销漆器。八角形盒身髹黑漆，表面用金漆（描金）绘制中国传统的山水建筑及人物故事。这种黑漆描金家具及器物在18、19世纪的欧洲贵族阶层中引发了疯狂的“中国风”热潮。', 'http://localhost:8080/files/7f75612c-cc40-4ceb-a811-9b2cadd9e4a4.png', 0, '海上丝绸之路与外销艺术展厅', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (163, '元至正刻本《大方广佛华严经》', '佚名', '古籍文献', '元代', '馆藏珍稀的元代佛经善本。经书采用经折装，纸张坚韧，墨色如漆。虽然历经数百年，但版面文字依然清晰如初。元代中晚期官刻本佛经传世极少，该经书具有极高的版本学与佛教文化研究价值。', 'http://localhost:8080/files/cac3bb8a-8e95-4290-8f9a-6a17d5c2834c.png', 2, '宗教文献特展区', '广东省博物馆', NULL, '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (165, '清代外销银累丝鎏金烧蓝寿字纹香熏', '广州银匠', '珍宝', '清代', '清代广州外销银器的巅峰代表作。香熏通体采用细如发丝的纯银丝编织（累丝）而成，表面鎏金并运用了独特的“烧蓝（珐琅）”工艺，呈现出迷人的蓝绿色彩。整件器物玲珑剔透，代表了当时中国银器制作的最高水平。', 'http://localhost:8080/files/6ac2a518-da07-4cea-9309-a115d0d24be7.png', 1, '外销奢侈品专展区', '广东省博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:26:19');
INSERT INTO `artifact` VALUES (167, '元解縉书大字诗轴', '解缙', '法书', '元末明初', '国家一级文物。明代内阁首辅、《永乐大典》总纂官解缙的狂草代表作。此轴书写气势磅礴，用笔跌宕起伏，线条流畅而极具张力，体现了解缙高超的草书造诣与狂放不羁的才子气质，是元末明初书法艺术的奇珍。', 'http://localhost:8080/files/261f19f3-0483-4d41-bd98-f6f9413e90ee.png', 0, '历代书法展厅/明清区', '广东省博物馆', NULL, '2026-05-25 18:27:19');
INSERT INTO `artifact` VALUES (168, '明董其昌行书临柳公权玄秘塔碑轴', '董其昌', '法书', '明代', '明代书画巨匠董其昌的行书晚年精品。此作虽为临摹唐代柳公权《玄秘塔碑》，但全以董氏自身标志性的“生拙秀润”笔意出之，不着意于形似，而得其神髓。布局章法疏朗，墨色燥润相兼，极具禅意。', 'http://localhost:8080/files/b3e93124-8d5f-4429-bea8-280f460bdfb0.jpg', 0, '历代书法展厅/明清区', '广东省博物馆', NULL, '2026-05-25 18:27:19');
INSERT INTO `artifact` VALUES (169, '明陈献章草书诗卷', '陈献章', '法书', '明代', '岭南大儒、江门学派创始人陈献章（白沙先生）的代表墨宝。陈白沙以发明“茅龙笔”（以广东新会圭峰山茅草制成的硬毫笔）闻名于世。此卷书法多用茅龙笔书写，笔锋苍劲生辣，飞白断续处如枯藤盘绕，形成了风靡全国、独树一帜的“白沙体”。', 'http://localhost:8080/files/18208cba-b37a-43fd-85f7-94030cd259f1.jpg', 0, '岭南历代书法展厅', '广东省博物馆', NULL, '2026-05-25 18:27:19');
INSERT INTO `artifact` VALUES (170, '清康熙御书“正大光明”匾额墨迹行书轴', '康熙帝', '法书', '清康熙', '清圣祖康熙皇帝（爱新觉罗·玄烨）的亲笔御书。康熙帝一生酷爱董其昌书法，此作结字规整，笔法圆劲，既有文人的清秀神韵，又兼具皇家独有的沉稳与威严气度，是研究清代帝王书法及宫廷文化的重要实物。', 'http://localhost:8080/files/70f83ed8-869a-4a04-b5ef-774e64f2ef4c.jpg', 0, '明清皇家艺术特展区', '广东省博物馆', NULL, '2026-05-25 18:27:19');
INSERT INTO `artifact` VALUES (171, '清邓石如篆书阴符经轴', '邓石如', '法书', '清代', '清代碑学巨贾邓石如的篆书代表作。该作结体严谨而舒展，用笔融入了隶书的笔意，打破了传统玉箸篆的死板。笔力雄厚，墨气淋漓，完美展现了清代中后期“以隶作篆”的碑派大印风格，对后世书坛影响深远。', 'http://localhost:8080/files/9f9cc560-dbdb-4bf6-929c-453d0d039c3a.png', 0, '历代书法展厅/碑学专区', '广东省博物馆', NULL, '2026-05-25 18:27:19');
INSERT INTO `artifact` VALUES (172, '西汉刘胜金缕玉衣', '佚名', '玉石器', '西汉', '国家首批禁止出国（境）展览文物，出土于满城汉墓。由2498片上等中山国玉片用金丝编缀而成。玉衣分头罩、上衣、裤筒、手套和鞋五部分，工艺精绝，是我国考古发掘中时代最早、保存最完整的金缕玉衣，彰显了汉代顶级的丧葬礼制。', 'http://localhost:8080/files/ce6fd9c1-7263-46a2-ad74-7f134fc37122.png', 0, '满城汉墓出土文物展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (173, '西汉窦绾透雕双龙衔环谷纹玉璧', '佚名', '玉石器', '西汉', '国家一级文物，出土于满城汉墓窦绾墓。玉璧通体透雕加战国延续的谷纹，上方透雕双龙戏珠衔环，线条极其流畅洗练。此璧玉质莹润，雕工玲珑剔透，代表了汉代玉器制作艺术的极高成就。', 'http://localhost:8080/files/22c3643a-e4f8-43db-bc91-9a1b395db36e.png', 0, '满城汉墓出土文物展厅', '河北博物馆', '', '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (174, '战国透雕双龙三凤纹玉佩', '佚名', '玉石器', '战国', '出土于河北平山三县中山国 。玉佩呈扁平状，采用精湛的透雕工艺刻画出双龙相互盘绕、三只凤鸟穿插其间的宏大构图。具有浓郁的北方中山国神秘、灵动的艺术风格。', 'http://localhost:8080/files/3fd83e3d-6aaf-47d3-8285-40538e871ec6.png', 0, '战国雄风-古中山国展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (175, '明代青玉镂雕松鹿纹笔筒', '佚名', '玉石器', '明代', '由整块青玉镂雕而成，筒身外壁雕刻有茂密的松林、奔跑的祥鹿以及灵芝等图案，寓意“松鹿同春、长寿富贵”。刀法深峻，层次分明，是明代文房玉器中的上乘之作。', 'http://localhost:8080/files/14d14f04-79f7-4b65-941f-f1fffa52bd60.png', 0, '馆藏历代玉器陈列', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (176, '明代红地缂丝云龙纹服饰残片', '佚名', '织绣', '明代', '采用了“一寸缂丝一寸金”的顶级缂丝工艺制作。在红色的丝底上，用各色丝线及金线缂织出五彩祥云与奔腾的巨龙。龙形威猛，缂工极为细致，是研究明代高等级宫廷织绣技术的重要标本。', 'http://localhost:8080/files/c2c5efb5-ce3a-4e07-9ef1-4c4dff95d025.png', 0, '纺织服饰陈列库', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (177, '清代刺绣八仙过海图条屏', '佚名', '织绣', '清代', '北方民间刺绣（北方多流行京绣、鲁绣风格）的代表作。采用高密度丝线，在缎面上绣出八仙各显神通跨越波涛的经典场景。色彩对比强烈，人物开脸生动，衣褶线条流畅。', 'http://localhost:8080/files/86ed7a46-4405-49f7-aa42-138a1e9a6261.png', 1, '民俗与民间艺术展厅', '河北博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (178, '清光绪石青地平金绣蟒纹吉服袍', '佚名', '织绣', '清光绪', '清晚期北方高官或王室成员穿着的吉服。石青色缎地，通体运用“平金绣”技法绣制九条金蟒，间饰五彩祥云与下幅的八宝立水纹。绣工规整严谨，尽显晚清宫廷服饰的繁缛之美。', 'http://localhost:8080/files/3f6077a5-de10-4c31-885b-d7b9f35722f0.png', 0, '馆藏晚清服饰展', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (179, '清乾隆掐丝珐琅番莲纹双耳炉', '内务府造办处', '珐琅器', '清乾隆', '标准的清代宫廷景泰蓝。器表以经典的松石绿珐琅釉为地，填烧红、黄、紫等各色番莲纹。掐丝线条流畅而刚劲，镀金厚实明亮，带有鲜明的乾隆朝“造办处”工艺特征，极为富丽堂皇。', 'http://localhost:8080/files/a5b03705-4d57-4260-9780-fdd61c318ddb.png', 0, '明清工艺珍宝展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (180, '清中期画珐琅缠枝牡丹纹寿字赏瓶', '佚名', '珐琅器', '清中期', '铜胎画珐琅器。瓶身线条优雅，在外壁细腻的白釉地上用珐琅料彩绘繁复的缠枝牡丹纹，并在腹部核心位置写有规整的“寿”字。此瓶既有瓷器之秀美，又有金属珐琅之华贵。', 'http://localhost:8080/files/0c670ca8-9521-493c-9649-95514b36a30b.png', 0, '明清工艺珍宝展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (181, '清晚期掐丝珐琅多宝如意', '佚名', '珐琅器', '清晚期', '清代宫廷逢年过节或帝王祝寿时常见的陈设珍玩。如意通体以掐丝珐琅工艺装饰，首、中、尾三处镶嵌有吉庆纹饰，色彩斑斓，工艺繁复，具有极高的吉祥寓意与观赏价值。', 'http://localhost:8080/files/340bdef1-6cc1-48b9-b802-b3399dccd65d.png', 0, '明清工艺珍宝展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (182, '西汉扣银漆奁', '佚名', '漆器', '西汉', '出土于满城汉墓，是汉代上层贵族妇女使用的化妆盒。木胎，内外髹黑漆与红漆。其最大特色在于口沿和边缘处镶扣有精美的银边（即扣银工艺），不仅增加了器物的坚固度，更平添了一丝高贵。', 'http://localhost:8080/files/9afb06af-c5df-4239-9b49-da4f857f5f35.png', 0, '满城汉墓出土文物展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (183, '明代剔红高士登高图圆盒', '佚名', '漆器', '明代', '精美的剔红（雕漆）代表作。盒盖表面髹数十层红漆后，雕刻出高山、古松、流云以及一位文人登高远眺的场景。雕刻刀法利落，画面意境深远，体现了明代雕漆工艺的高超水平。', 'http://localhost:8080/files/0a8be4c2-4416-4448-8591-929bde0f7943.png', 0, '馆藏明清工艺品展', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (184, '清代黑漆螺钿山水亭台纹文具箱', '佚名', '漆器', '清代', '采用复杂的螺钿漆艺制作。通体髹黑漆，表面利用色彩斑斓的贝壳薄片（螺钿）拼嵌出细腻的江南山水、亭台楼阁和泛舟图景。在光线照射下，黑漆与螺钿交相辉映，流光溢彩。', 'http://localhost:8080/files/217a1bb1-61f3-4be0-a524-36c00f3104ff.png', 1, '馆藏明清工艺品展', '河北博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (185, '元刻本《新刊大宋宣和遗事》', '佚名', '古籍文献', '元代', '院藏极其珍稀的元代刻本，属海内孤本或极其罕见的善本。该书记述了宋徽宗宣和年间的朝政及宋江三十六人起义等故事，是《水浒传》的重要蓝本之一。版刻字迹古朴，是研究中国小说史与元代印刷史的无上珍宝。', 'http://localhost:8080/files/6d9c5aff-51b1-4ced-a339-676c17f78a21.png', 0, '古籍善本特藏库', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (186, '明万历明内府刻本《大明会典》', '明官修', '古籍文献', '明万历', '明代万历年间的宫廷内府刻本。详细记载了明代从中央到地方的官制、礼仪、法律、军政等各项典章制度。纸张采用名贵的皮纸，印刷精美，装帧考究，是研究明代历史核心的官修文献。', 'http://localhost:8080/files/2d2a11c7-b337-4913-9508-8eff1ef71e09.png', 0, '古籍善本阅览室', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (187, '清代直隶总督署档案公文抄本', '直隶总督署官员', '古籍文献', '清代', '具有极高地方历史价值的直隶（今河北及周边地区）官方政治文献。内容涵盖了清代历任直隶总督（如李鸿章、曾国藩等）在任期间的奏折抄本、地方政务批复等，是研究清代直隶地区发展的独家档案。', 'http://localhost:8080/files/354cf160-e1e1-40b0-b496-54c92d813109.png', 0, '近现代与地方文献库', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (188, '战国错金银四龙四凤铜方案座', '佚名', '珍宝', '战国', '国家首批禁止出国（境）展览文物，出土于平山古中山国寿王墓。此方案座极为精巧复杂，底部由四只跪卧的梅花鹿承托，中间四龙四凤相互纠缠纠结，龙身凤翅通体错金银。打破了中原传统青铜器的呆板，是战国青铜与贵金属镶嵌工艺的极品。', 'http://localhost:8080/files/25bb8f87-bf8c-44ef-a392-d26d644a360b.png', 0, '战国雄风-古中山国展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (189, '西汉错金博山炉', '佚名', '珍宝', '西汉', '国家首批禁止出国（境）展览文物，出土于满城汉墓。炉身似海中仙山“博山”，通体运用极细的金丝错出神仙、奇兽与流云纹饰。香料点燃后，烟气从山峦间的孔洞中袅袅飘出，宛如仙境，是汉代浪漫主义与错金工艺的最高峰。', 'http://localhost:8080/files/8e98d085-c65e-459d-ba1c-278c74736dc5.png', 0, '满城汉墓出土文物展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (190, '战国错银双翼神兽', '佚名', '珍宝', '战国', '出土于古中山国遗址，是中山国独有的神话图腾怪物。神兽似狮似虎，背生双翼，作咆哮奔跑状。通体错银，饰以变形云纹，威武凶猛中带着一丝诡谲，极具北方游牧民族与中原文化碰撞的独特美感。', 'http://localhost:8080/files/7b08bf95-ee8b-4ab9-9f34-57a531465500.png', 0, '战国雄风-古中山国展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (191, '明张瑞图行草书五言诗轴', '张瑞图', '法书', '明代', '明末著名书家“晚明四大家”之一张瑞图的行草书代表作。张瑞图的书法以折带波臣、奇逸峻峭著称。此作章法紧凑，用笔多用侧锋、方笔，转折处如斩钉截铁，充满了强烈的节奏感与文人傲骨。', 'http://localhost:8080/files/58652a64-d202-4717-940f-0f7493bd0835.png', 0, '馆藏历代书法展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (192, '清刘墉行书临苏轼诗轴', '刘墉', '法书', '清代', '清代著名书家、“浓墨宰相”刘墉（刘罗锅）的行书精品。此轴临写苏东坡诗意，用墨极其浓厚，笔力内敛，体势丰腴。看似笨拙，实则骨力长存，深得“棉里裹铁”的刘氏书法精髓。', 'http://localhost:8080/files/bdec0869-1c90-4b47-b5ff-7a0cefaf2b28.png', 0, '馆藏历代书法展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (193, '清郑燮行草书竹石诗轴', '郑燮', '法书', '清代', '“扬州八怪”之一郑板桥的传世墨宝。此作采用了他独创的“六分半书”（将隶书、楷书、行草融入画竹之法）。字形歪歪斜斜却乱石铺街、错落有致，并配有他标志性的题画竹石诗，书画一体，极具个性。', 'http://localhost:8080/files/520051d9-e61e-40dc-8f48-4be06c5a3d9f.png', 0, '馆藏历代书法展厅', '河北博物馆', NULL, '2026-05-25 18:29:04');
INSERT INTO `artifact` VALUES (194, '晋顾恺之洛神赋图卷', '顾恺之(传)', '绘画', '东晋', '上博馆藏书画的镇馆之宝级别巨作。此卷虽为宋代摹本，但极为完美地保留了东晋顾恺之画风的神韵。画面根据曹植《洛神赋》创作，采用连环画式的构图，描绘了曹植与洛神真挚动人又怅惘分离的爱情故事，线条如“春蚕吐丝”，艺术价值极高。', 'http://localhost:8080/files/d0ff4c8a-f70c-433c-8576-5d541f252a85.jpg', 0, '中国历代绘画馆/1号特展柜', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (195, '唐孙位高逸图卷', '孙位', '绘画', '唐代', '国家一级文物，是唐代晚期画坛巨匠孙位唯一的传世真迹。画面描绘了魏晋时期“竹林七贤”中的山涛、王戎、刘伶、阮籍四位高士的闲适生活。人物神态刻画入木三分，衣褶孤高，是研究唐代人物画及魏晋名士风度的旷世孤本。', 'http://localhost:8080/files/83a4d101-7352-4346-aa0b-a5fbbb0d7608.jpg', 0, '中国历代绘画馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (196, '明沈周庐山高图轴', '沈周', '绘画', '明代', '“明四家”之首沈周为祝贺其老师陈宽七十大寿而创作的杰作。全图师法元代王蒙，用笔繁密，层峦叠嶂，气势雄浑，成功将庐山的崇高壮丽与对恩师的崇敬之情完美融合，是明代吴门画派全景式山水画的巅峰代表作。', 'http://localhost:8080/files/61177ea0-669b-4d92-ab04-dc62bb3817f8.jpg', 0, '吴门书画特展区', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (197, '清朱耷孤禽图轴', '朱耷(八大山人)', '绘画', '清代', '清代杰出写意大家八大山人的经典之作。画面极其精简，仅在白纸中央绘有一只单足独立、翻着白眼的孤鸟。整幅画作墨气淋漓，通过极度夸张和冷峻的造型，宣泄了作者作为明朝皇室后裔对清廷的不合作态度与内心的孤傲愤懑。', 'http://localhost:8080/files/2e47f0de-3f3d-482b-9ac1-e22ab8673bc3.jpg', 0, '中国历代绘画馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (198, '良渚文化神人兽面纹玉琮', '佚名', '玉石器', '新石器时代', '出土于太湖流域良渚文化核心遗址，是古代祭地的最高礼器。玉琮外方内圆，四角用极其细微的阴线錾刻出神人兽面纹徽章，工艺精密得令人叹为观止，是研究史前宗教崇拜、巫术与玉器切割工艺的核心物证。', 'http://localhost:8080/files/f56e2812-f17e-4203-9ed1-177adf36a555.jpg', 0, '中国古代玉器馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (199, '西汉透雕双龙纹玉璧', '佚名', '玉石器', '西汉', '上等和田青玉雕琢，璧身布满规整的蒲纹。两侧透雕有一对对称的游龙，龙身蜿蜒扭曲，极具汉代有雄浑、张扬的动态美。该璧出土时保存极好，玉质受沁后呈现出迷人的古玉光泽。', 'http://localhost:8080/files/61c2b1d6-37ce-436d-b9fa-3c9df9995cad.jpg', 0, '中国古代玉器馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (200, '清乾隆白玉桐荫仕女图两层珍玩', '内务府造办处', '玉石器', '清乾隆', '一件巧夺天工的“俏色”玉雕传奇。造办处玉工利用一块带有天然裂纹和黄色玉皮的和田白玉料，因材施艺，将其雕刻为一扇微开的红漆大门，门内一个仕女向外窥探，门外坐一仕女。巧妙将瑕疵化为江南桐荫庭院的绝妙景致。', 'http://localhost:8080/files/c38acfba-a0ed-4b91-b52e-e4095e0d9201.jpg', 0, '明清珍玩陈列区', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (201, '明代顾绣花鸟图册页', '韩希孟', '织绣', '明代', '上海本土诞生的非物质文化遗产“顾绣”（露香园顾氏家族刺绣）的极品。由明代针神韩希孟亲手刺绣。她“以针代笔，以线代墨”，将宋元名家花鸟画完美还原在丝绢之上，针法多变，晕色细腻，达到了“画绣一体”的最高艺术境界。', 'http://localhost:8080/files/809f343c-c4f8-47c7-96bc-17310a825f71.jpg', 0, '中国历代织绣馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (202, '清中晚期红地缂丝百子迎春图挂轴', '佚名', '织绣', '清代', '采用顶级通经断纬缂丝工艺。大红丝缎底色上缂织出上百个形态各异、正在燃放鞭炮、舞龙戏耍的童子形象。构图热闹繁密，色彩五彩缤纷，具有极高的节日喜庆色彩和晚清宫廷织绣工艺价值。', 'http://localhost:8080/files/eaf5be15-8841-41d4-8afe-8575ebf53a71.jpg', 1, '中国历代织绣馆', '上海博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (203, '明黄色缎地刺绣十二章纹龙袍料', '明代官织', '织绣', '明代', '明代江南织造局为宫廷定制的龙袍未剪裁面料。黄色缎面上用纯金线和五彩丝线绣有正龙、行龙及古代帝王专用的“十二章纹”（日、月、星辰、山、龙等）。绣工严丝合缝，富丽堂皇。', 'http://localhost:8080/files/48ebfe96-7978-4dc2-bd5c-407fec0d1c66.jpg', 0, '织绣特藏库', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (204, '明景泰掐丝珐琅缠枝莲纹八宝大大盘', '御用监', '珐琅器', '明景泰', '带有着正宗明代官窑“景泰年制”款识的掐丝珐琅（景泰蓝）传世重器。盘心以极深的宝石蓝珐琅釉为地，中心掐丝绘制缠枝莲花，四周环绕佛教八宝纹。珐琅釉发色纯正，具有典型的明代金属胎珐琅的大气风格。', 'http://localhost:8080/files/bdc95322-1b22-4adc-bba7-f7a88b6325a0.jpg', 0, '中国明清工艺馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (205, '清乾隆画珐琅山水人物图方洗', '内务府造办处', '珐琅器', '清乾隆', '清代宫廷御用笔洗。四方形铜胎，内壁和外壁均敷有白色的珐琅釉，并由宫廷画师用细腻的笔触手绘出高士临流、远山如黛的中国传统山水画，工艺极其高雅精细。', 'http://localhost:8080/files/0b041156-94d6-4756-bc71-b0ad21262320.png', 0, '明清工艺珍宝展厅', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (206, '清中期錾胎珐琅拐子龙纹兽耳尊', '佚名', '珐琅器', '清中期', '仿商周青铜器造型，两侧饰以兽首耳。采用錾胎珐琅工艺，在凸起的青铜线条间填烧各色珐琅料。由于錾胎工艺比普通掐丝更费铜料和工时，此类器物具有极强的立体力量感，属于皇家陈设规格。', 'http://localhost:8080/files/9db0e4f7-9f6c-41c6-be6c-e4df1c7b59f0.jpg', 0, '中国明清工艺馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (207, '元代张成造剔红栀子花纹圆盘', '张成', '漆器', '元代', '国家一级文物。元代雕漆一代宗师张成的传世神作。盘内髹厚重红漆，雕刻一朵盛开的栀子花及含苞待放的花蕾，叶片翻卷舒展。刀法圆润流畅，毫无锋芒外露之感，盘底针刻“张成造”三字篆书款，是世界漆器史上里程碑式的珍宝。', 'http://localhost:8080/files/8f9f7f70-fa69-4caf-a5ac-fd9fccd251e5.jpg', 0, '中国历代漆器馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (208, '明宣德剔彩双龙戏珠纹大承盘', '漆作官窑', '漆器', '明宣德', '采用极为复杂的“剔彩”工艺（在胎体上分层髹涂红、绿、黄等不同颜色的漆层，雕刻时根据需要剔出不同漆层以显现色彩）。盘面描绘两条巨龙在云海中争夺火珠，色彩斑斓，层次分明，极具皇家威仪。', 'http://localhost:8080/files/317e2271-2ecc-4b9d-b7f0-977c6bb6c0a4.jpg', 0, '中国历代漆器馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (209, '清乾隆黑漆螺钿百寿图文具桌', '佚名', '漆器', '清乾隆', '一柄高等级清代宫廷漆器家具。桌身髹黑漆，桌面及四周边缘采用极其精细的薄螺钿工艺，拼嵌出一百个字体各异的“寿”字以及繁复的万字不到头花纹。黑漆之沉稳与螺钿之流光溢彩完美契合。', 'http://localhost:8080/files/ee638bcc-9034-420c-8e8d-47e1119ef078.jpg', 0, '明清家具陈列馆', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (211, '宋刻本《东坡乐府》', '苏轼', '古籍文献', '宋代', '院藏极其珍稀的宋代雕版印刷善本。收录了北宋大文豪苏东坡毕生创作的词作（乐府）。纸张坚韧，采用宋代经典的柳体或颜体字进行雕刻，版面舒朗尊贵。宋刻本在古籍界有“一页宋版一两黄金”之说。', 'http://localhost:8080/files/dde9b868-c3b6-4d47-8e7f-7447cc8abbc3.jpg', 0, '古籍善本阅览室', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (212, '明代顾氏露香园丛书木刻本', '顾清等撰', '古籍文献', '明代', '明代上海本地文化名门“露香园顾氏”私人刻印的丛书。该书校勘极精，字体清秀，代表了明代江南地区私人刻书、藏书文化的最高学术及工艺水平，对于研究明代江南社会文化和印刷史有极高价值。', 'http://localhost:8080/files/45f13b60-f480-4684-8b0a-e92bcb60b065.png', 0, '上海地方文献陈列室', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (213, '清金累丝镶嵌五蝠捧寿九珠凤冠', '内务府造办处', '珍宝', '清代', '清代高等级王妃或一品诰命夫人新婚、盛典时佩戴的奢华凤冠。全冠采用纯金丝手工编织（累丝）出五只祥蝠与三只凤凰，凤凰背部及冠身镶嵌有九颗滚圆、光泽莹润的天然大珍珠，工艺极其繁复，华贵无双。', 'http://localhost:8080/files/ae75141e-09dd-4d3d-bcb9-3e6babcec518.jpg', 0, '明清工艺珍宝展厅', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (214, '清代点翠镶嵌红蓝宝石如意簪', '佚名', '珍宝', '清代', '慈禧太后时期风格的宫廷高级发饰。利用翠鸟背部亮丽的蓝色羽毛贴嵌在金质发簪底托上（点翠），历经百年依然呈现出迷人的翠蓝色光泽。簪首中心更镶嵌有高纯度的红宝石与蓝宝石，交相辉映，极尽奢靡。', 'http://localhost:8080/files/5c9a05d6-bc01-4e89-b420-b7b649cf3869.jpg', 1, '明清工艺珍宝展厅', '上海博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (215, '明末项圣谟金笺纸本设色山水扇面珍玩', '项圣谟', '珍宝', '明末清初', '这是一件将高级艺术与贵金属材质完美结合的“案头珍玩”。折扇面采用纯金箔铺底（金笺纸），明末名家项圣谟在其上用细笔工笔设色绘制了江南隐逸山水图。由于金笺纸极难着墨着色，该作品历经岁月洗礼仍金光闪闪、画意盎然。', 'http://localhost:8080/files/78814472-9d0c-4402-ad28-4f5cd20885f3.jpg', 0, '历代珍玩特展区', '上海博物馆', NULL, '2026-05-25 18:33:42');
INSERT INTO `artifact` VALUES (216, '宋拓晋唐历代名家法帖（粤雅堂本）', '历代名家书, 宋代拓工', '碑帖', '宋代拓本', '国家一级文物。此本为宋代精拓的历代名家法帖真迹，后由岭南著名藏书家伍崇曜辑入《粤雅堂丛书》。拓本字迹清晰，保留了晋唐大书家如王羲之、献之、颜真卿等人的核心神韵，是岭南地区传世碑帖收藏中的泰斗之作。', 'http://localhost:8080/files/8843ab57-a02d-46c5-bcf3-d026e1fe213f.jpg', 0, '古籍善本与碑帖展厅', '广东省博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (217, '明拓唐李邕书叶有道碑册', '李邕(书), 明代拓工', '碑帖', '明代拓本', '唐代大书法家李邕（李北海）撰文并书写的名碑明代拓本。李邕书法以“行书入碑”闻名，笔力遒劲。此明拓本原石后毁，故此本极好地还原了李氏行楷书体字形欹侧、骨气洞达的原始风貌，极为罕见。', 'http://localhost:8080/files/7a2f0ac7-b1b1-40ef-9c26-9c012010b309.jpg', 0, '历代书画陈列室', '广东省博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (218, '清拓汉张迁碑册', '汉代无名氏书, 清代拓工', '碑帖', '清代拓本', '汉代名碑《张迁碑》的清中期精拓本。该碑是汉隶（隶书）臻于成熟鼎盛时期的代表作，字形方整多变，拙中带巧。清代碑学兴起后，此拓本成为岭南及全国书法家研习汉隶、寻根溯源的必备范本。', 'http://localhost:8080/files/4f2e625d-94c3-479b-86f8-d6dcd7faf1a0.jpg', 1, '古籍善本与碑帖展厅', '广东省博物馆', '上海博物馆西馆二楼西区', '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (219, '清康熙御制翻刻淳化阁帖册', '历代书家, 清宫廷拓工', '碑帖', '清康熙', '清代康熙皇帝下令以内府所藏宋代《淳化阁帖》为蓝本，命内廷工匠重新翻刻上石并精拓而成的内府赏赐本。黑底白字，墨色如漆，纸张采用高档宫廷夹江纸，带有浓郁的清代皇家书学正统风格。', 'http://localhost:8080/files/e7227f52-33a6-4e97-b5f4-759e383123b7.jpg', 0, '明清工艺陈列区', '广东省博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (220, '北宋拓北魏始平公造像记册', '朱义章(书), 北宋拓工', '碑帖', '北宋拓本', '龙门二十品之首《始平公造像记》的北宋早期拓本。原石为北魏太和二十二年刻，是龙门造像记中唯一的阳刻（字形凸起）作品。北宋拓本字口毫无剥蚀，极好地展现了魏碑（北碑）方笔斩钉截铁、雄强浑厚的原始刀锋力道。', 'http://localhost:8080/files/9dbe2dac-3d3b-4c08-a1c5-ea9e7cc7aa2b.png', 0, '石刻计划与碑帖特展区', '河北博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (221, '明拓唐颜真卿大唐中兴颂碑册', '颜真卿(书), 明代拓工', '碑帖', '明代拓本', '唐代著名书家颜真卿摩崖石刻《大唐中兴颂》的明代原石拓本。此碑字大如拳，颜体楷书在此作中达到了“端庄雄伟、气势磅礴”的巅峰。明拓本完整保留了原石未遭严重风化前的摩崖字口，是北方碑学研究的重器。', 'http://localhost:8080/files/eddcdbce-3ad1-4503-a5ae-1874f3cafad8.png', 0, '馆藏历代碑帖陈列', '河北博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (222, '清拓汉封龙山颂碑册', '汉代无名氏书, 清代拓工', '碑帖', '清代拓本', '《封龙山颂》原石位于河北元氏县封龙山，是记录北方汉代祭祀山神的重要碑刻。清代中晚期著名书家发掘并精拓此本。该拓本完美呈现了该碑字形舒展、笔画劲挺中带有篆书笔意的独特汉隶风格，极具地方历史文献价值。', 'http://localhost:8080/files/b59c143b-922f-49ad-b65b-48a326a5b12d.png', 0, '河北地方石刻风貌展', '河北博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (224, '北宋拓宋代翻刻王羲之十七帖（游相本）', '王羲之(书), 宋代拓工', '碑帖', '北宋拓本', '国家一级文物，上博碑帖收藏的镇馆之宝。此为南宋宰相游似当年收藏的“游相十本”之一。根据唐代弘文馆所藏王羲之草书信札精细刻石并于北宋初年拓印，纸墨极古，传世极为罕见，被历代书家奉为“阁帖之冠”。', 'http://localhost:8080/files/b4c98cf2-5abd-4464-a928-ce7048f65c5d.jpeg', 0, '中国历代书法馆/碑帖专柜', '上海博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (225, '唐拓隋丁道护启法寺碑册（孤本）', '丁道护(书), 唐代拓工', '碑帖', '唐代拓本', '海内绝无仅有的“唐拓孤本”。原石为隋代著名书家丁道护所书，其书法承前启后，融合了魏碑的骨力与唐楷的法度。该唐拓本墨色淡雅，字迹清秀，由于原碑在唐代以后便告毁佚，此拓本便成了世间唯一的传世实物。', 'http://localhost:8080/files/728afc79-c7c7-431e-8f2b-c1c5d1c6c6fd.jpg', 0, '中国历代书法馆/碑帖专柜', '上海博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (226, '宋拓唐柳公权神策军碑册', '柳公权(书), 宋代拓工', '碑帖', '宋代拓本', '晚唐大书家柳公权奉旨书写的楷书巅峰之作。原石刻于皇宫禁地，后毁。此宋拓本（通常为剪裱册页形式）极为珍贵，字口锋芒毕露，完美展现了柳体“棱角分明、骨力遒劲”的楷书神髓，是不可多得的国宝级碑帖。', 'http://localhost:8080/files/c3c6a2ce-dbab-4e9d-b068-0aece7b2cde5.jpg', 0, '碑帖善本特藏库', '上海博物馆', NULL, '2026-05-25 18:35:43');
INSERT INTO `artifact` VALUES (228, '宋拓唐欧阳询九成宫醴泉铭册', '欧阳询(书), 宋代拓工', '碑帖', '宋代拓本', '“天下第一正书”唐代欧阳询《九成宫醴泉铭》的宋代精拓本。欧体楷书以“法度严谨、险绝俊秀”冠绝天下。此宋拓本在历代藏家手中流传，保留了最初始的笔画粗细对比与险绝结构，是研究欧体书法的最高母本。', 'http://localhost:8080/files/6a0ab943-ab5f-472a-b31b-24b49a276a3a.jpg', 0, '中国历代书法馆/碑帖专柜', '上海博物馆', NULL, '2026-05-25 18:35:43');

-- ----------------------------
-- Table structure for artifact_loan_request
-- ----------------------------
DROP TABLE IF EXISTS `artifact_loan_request`;
CREATE TABLE `artifact_loan_request`  (
  `req_id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` bigint NOT NULL COMMENT '关联的巡展申请ID',
  `artifact_id` bigint NOT NULL COMMENT '文物ID',
  `artifact_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文物名称（冗余，方便查询）',
  `owner_museum` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文物所属博物馆',
  `status` tinyint NULL DEFAULT 0 COMMENT '0-待审批 1-已同意 2-已拒绝',
  `audit_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批备注',
  `audit_time` datetime NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `is_finalized` tinyint NULL DEFAULT 0 COMMENT '是否已签发: 0-草稿 1-已签发',
  PRIMARY KEY (`req_id`) USING BTREE,
  INDEX `app_id`(`app_id` ASC) USING BTREE,
  INDEX `artifact_id`(`artifact_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文物借用子申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
