-- ----------------------------
-- Table structure for banner
-- ----------------------------
DROP TABLE IF EXISTS `banner`;
CREATE TABLE `banner`  (
  `banner_id` bigint NOT NULL AUTO_INCREMENT,
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片URL',
  `link_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '跳转链接',
  `sort` int NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint NULL DEFAULT 1 COMMENT '0-隐藏 1-显示',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`banner_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '首页Banner表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of banner
-- ----------------------------

-- ----------------------------
-- Table structure for exhibition_application
-- ----------------------------
DROP TABLE IF EXISTS `exhibition_application`;
CREATE TABLE `exhibition_application`  (
  `app_id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `applicant_id` bigint NOT NULL COMMENT '申请人ID(关联sys_user)',
  `title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '巡展主题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '巡展方案描述',
  `target_location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '巡展地点',
  `start_date` date NULL DEFAULT NULL COMMENT '预计开始日期',
  `end_date` date NULL DEFAULT NULL COMMENT '预计结束日期',
  `artifact_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请借用的文物ID集合(逗号分隔或关联中间表)',
  `status` tinyint NULL DEFAULT 0 COMMENT '审批状态: 0-待审批, 1-已通过, 2-已驳回',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批备注/驳回原因',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审批时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `time_slot_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '{\"09:00-12:00\": 100, \"12:00-17:00\": 100}' COMMENT '场次名额配置',
  `ticket_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '票价',
  `booking_notice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '预约须知',
  `max_capacity` int NULL DEFAULT 0 COMMENT '每日人数上限',
  `cover_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '巡展封面图地址',
  `ticket_types` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  PRIMARY KEY (`app_id`) USING BTREE,
  INDEX `applicant_id`(`applicant_id` ASC) USING BTREE,
  CONSTRAINT `exhibition_application_ibfk_1` FOREIGN KEY (`applicant_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '巡展申请审批表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of exhibition_application
-- ----------------------------
INSERT INTO `exhibition_application` VALUES (50, 2, '【河北博物馆】青铜器展览', '绝无仅有的“国宝级”重器扎堆，国之重器密集度极高。', '河北博物馆东馆二楼', '2026-05-25', '2026-06-30', '102,136,137,138,139', 1, '策展方确认办展，系统自动通过', '2026-05-25 19:47:50', '2026-05-25 19:43:38', '[{\"name\":\"全天\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":500}]', 0.00, '为你整理好了一份适用于河北博物馆（官方微信小程序、售票官网、或展厅入口公示牌）的游客须知与购票/退票守则。\n\n你可以直接将以下内容配置到你的系统前端或公告模块中：\n\n🏛️ 河北博物馆 · 观众入馆须知与票务守则\n一、 💡 观展注意事项\n实名预约入馆：所有观众（含免费及优惠对象）均需提前通过官方渠道进行实名预约，携带二代身份证原件或预约二维码刷闸机入馆。\n\n保持文明静谧：展厅内请勿大声喧哗、追逐打闹；请将手机调至静音或震动模式，以免影响他人观展。\n\n严禁拍照闪光：基于文物保护要求，全馆展厅内禁止使用闪光灯、三脚架和自拍杆。\n\n衣冠整洁入场：酗酒者、衣冠不整者（如穿拖鞋、赤膊等）以及携带宠物者谢绝入馆。\n\n幼童看护原则：行动不便的老年人、残疾人以及学龄前儿童，须由成年人陪同看护入馆。\n\n二、 🚫 禁止携带物品清单（严禁带入展厅）\n为保障文物安全与公共安全，以下物品禁止带入馆内：\n\n管制及危险物品：枪支弹药、管制刀具、易燃易爆品、剧毒及放射性物品。\n\n大件行李及工具：体积超过 40×40 厘米 的大件行李箱/包（请先至寄存处寄存）、各类滑板车、平衡车。\n\n液体与食品：易污染展厅环境的各类有色饮料、黏性食品、生鲜物品。\n\n专业摄录设备：未获馆方许可的专业航拍无人机、商业摄影轨道。\n\n三、 🎟️ 社会福利票（特惠票）购买专属资格\n⚠️ 郑重提示：社会福利票（特惠/免费票）为国家定向福利，仅限以下特定人群预约或购买。入馆时须由本人同时出示身份证和有效福利证件进行双重核验：\n\n军人及优抚对象：现役军人、残疾军人、退役军人、烈士遗属、因公牺牲军人遗属、病故军人遗属（凭军官证、文职干部证、士兵证或退役军人优待证）。\n\n老年人：年满 60周岁 及以上的老年人（凭二代身份证、老年人优待证）。\n\n残疾人：持有中国残疾人联合会颁发的残疾证、伤残国家机关工作人员证者（凭残疾证原件）。\n\n※ 不符合上述条件者若误购、冒购此类票种，现场核验不予通过，将无法入馆。\n\n四、 🔄 退票规则与说明\n线上自主退票：在未检票出行的前提下，观众最晚可在预约当天闭馆前（如16:30前）通过原购买渠道申请无条件全额退票。\n\n逾期不可退改：超过预约当天闭馆时间、或门票已被核销检票的，系统将自动锁单，一律不予退改、不予退款。\n\n爽约惩罚机制：如因个人原因无法到馆且未及时在线上取消预约，累计爽约达到一定次数（如 3 次）的账户，系统将在接下来的一段时间内（如 30 天内）限制其继续预约。\n\n原路退款时效：退款申请审核通过后，票款将在 1-5 个工作日内 自动原路退回至您的支付账户（微信/支付宝/银行卡）。', 500, 'http://localhost:8080/files/90621519-bcf1-43d8-b790-5bd00be323d6.png', '[{\"name\":\"成人票\",\"price\":30},{\"name\":\"学生票\",\"price\":20},{\"name\":\"社会福利票\",\"price\":0}]');
INSERT INTO `exhibition_application` VALUES (51, 8, '【广东博物馆】越海流徽：岭南历代法书墨迹展', '“越海”代指古百越与南海丝路，地理特征明显；“流徽”语出古诗文，意为流传下来的美德、诗文或艺术光彩。名字温润高雅。', '广东博物馆A馆', '2026-05-25', '2026-06-30', '104,133,135', 1, '策展方确认办展，系统自动通过', '2026-05-25 20:10:12', '2026-05-25 20:08:32', '[{\"name\":\"上午入场\",\"timeRange\":[\"09:00\",\"12:00\"],\"quota\":400},{\"name\":\"下午入场\",\"timeRange\":[\"13:00\",\"18:00\"],\"quota\":600}]', 0.00, '特价票预约与购票须知\n⚠️ 【严正提示】\n本馆社会福利票（特价/免票）属国家定向福利，仅限特定符合条件的人群预约及购买。\n为确保文物安全与入馆秩序，本馆实行**“实名预约+现场双重核验”**制。非符合条件人员请勿错购、冒购，否则现场核验不予通过将无法入馆。\n一、 专属购票与预约资格\n只有符合以下条件的观众，方可预约或购买社会福利票，入馆时须由本人出示二代身份证原件及对应的有效福利证件：\n老年人群\n资格条件：年满 60周岁 及以上的老年人。\n核验证件：本人二代身份证 或 老年人优待证原件。\n残疾人群\n资格条件：持有中国残疾人联合会颁发的残疾证，或伤残国家机关工作人员。\n核验证件：本人有效残疾证原件 或 伤残国家机关工作人员证原件。\n军人及优抚对象\n资格条件：现役军人、残疾军人、退役军人，以及烈士遗属、因公牺牲军人遗属、病故军人遗属。\n核验证件：本人军官证、文职干部证、士兵证、学员证或退役军人优待证原件。\n\n二、 现场核验与入馆流程\n实名比对：入馆时需在专设的“绿色通道/福利核验窗口”排队，由工作人员进行人脸、身份证及物理证件的三合一比对。\n\n证件有效性：所有福利证件必须在有效期内，涂改、过期、伪造或照片模糊不清的证件一律视为无效。\n\n禁止代刷：福利票限本人使用，严禁冒用、代刷他人证件。一经发现，馆方有权谢绝入馆并依法暂扣冒用证件。\n\n三、 退票与改签规则\n自主退票时限：在未检票入馆的前提下，如因行程变动，观众最晚可在预约当天闭馆前（如16:30前）通过原购买渠道申请线上全额退票。\n\n逾期锁单不退：超过预约当天闭馆时间，或门票已被现场扫描核销的，系统将自动锁单，一律不予退改、不予退款。\n\n爽约惩罚机制：若成功预约福利票后未到馆，且未在规定时间内取消，累计爽约满 3 次的账户，系统将自动触发限制机制，在接下来的 30天内 将无法再次预约本馆的任何门票。\n退款原路返回：线上申请退款成功后，系统将在 1-5 个工作日内 将票款原路退回至您的支付账户（微信/支付宝/银行卡）。', 1000, 'http://localhost:8080/files/e3f440de-924c-4efe-ab8a-a8c503e099b7.png', '[{\"name\":\"普通票\",\"price\":15},{\"name\":\"特价票（购买资格请看详情）\",\"price\":5}]');
INSERT INTO `exhibition_application` VALUES (52, 11, '【上海博物馆】繁华落尽，墨润浮生：清代文人生活展', '摒弃了宏大的政治叙事，将视角对准清代文人的内心世界与精致的日常生活。“案头清供”指书房里的玉雕、墨砚、文具，给人一种“结庐在人境，心远地自偏”的优雅与静谧。', '上海博物馆西馆二楼西区', '2026-05-25', '2026-06-30', '148,177,184,218,202,214,165', 1, '策展方确认办展，系统自动通过', '2026-05-25 21:26:37', '2026-05-25 21:21:16', '[{\"name\":\"上午入场\",\"timeRange\":[\"09:00\",\"12:00\"],\"quota\":400},{\"name\":\"下午入场\",\"timeRange\":[\"13:00\",\"18:00\"],\"quota\":600}]', 0.00, '【上海博物馆】“繁华落尽，墨润浮生：清代文人生活展”参观须知\n摒弃了宏大的政治叙事，本次展览将视角精准对准清代文人的内心世界与精致的日常生活。从书房里的玉雕、墨砚，到几案前的文具清供，无不传递着“结庐在人境，心远地自偏”的优雅与静谧。\n\n为了给您营造一个高雅、安静且秩序井然的观展环境，更好地体味清代文人的墨润浮生，请在购票及入馆前仔细阅读以下参观须知：\n\n一、 🎟️ 票务配置与预约说明\n本展览实行全员实名制分时段预约，观众需根据自身条件选择对应票种并合理安排场次：\n\n成人票：适用于普通成年观众。\n\n学生票 / 儿童票：适用于在校学生及未成年儿童，入场时需核验相关学生证件。\n\n老年票 / 社会福利票（特惠免票）：\n\n老年票：限60周岁及以上老年人预约。\n\n社会福利票：仅限现役军人、残疾军人、退役军人、残疾人等国家定向福利群体预约。\n\n⚠️ 特别提示：购买老年票与社会福利票的观众，入馆时须由本人同时出示二代身份证原件和对应的有效福利证件（如残疾证、军官证、退役军人优待证等）进行现场双重核验。非符合条件人员请勿错购，否则核验不予通过将无法入馆。\n\n二、 ⏰ 场次管理与入馆时限\n上午场：入馆及检票时间为 09:00 - 13:00（请在对应时段内刷闸机进馆，错开高峰）。\n\n下午场：入馆及检票时间为 13:00 - 17:00（每日17:00停止检票入馆）。\n\n请严格按照您预约的场次时间前来参观。因个人原因迟到或错过对应场次，当日门票将自动失效。\n\n三、 🚫 展厅内禁止携带物品及行为规范\n文人书房，重在静谧与雅致。为保护传世书画、漆器及玉石器等脆弱文物，请遵守以下规定：\n\n严禁拍照闪光：展厅内严禁使用闪光灯、三脚架及自拍杆。强光和金属支架极易对古代书画和漆器造成不可逆的物理损伤。\n\n禁止携带大件物品：体积超过 40×40 厘米的行李箱、背包，以及滑板车等工具请先至寄存处寄存。\n\n严禁携带食品饮料：请勿将有色饮料、黏性食品、生鲜及宠物带入展厅，共同维护展厅的清洁环境。\n\n保持展厅静谧：请将手机调至静音或震动模式。展厅内请勿大声喧哗、追逐打闹，以免惊扰清代文人的“案头清供”之美。\n\n四、 🔄 退票与爽约规则\n无忧退票时限：在未检票入馆的前提下，如行程有变，最晚可在预约当天闭馆前（16:30前）通过系统原渠道申请线上全额退票。\n\n逾期锁单不退：超过预约当天闭馆时间，或门票已被核销检票的，系统将自动锁单，一律不予退改。\n\n爽约惩罚机制：若成功预约门票（含免费福利票）后未到馆参观，且未在规定时间内取消，累计爽约满 3 次的账户，系统将自动限制其在接下来的 30天内 再次预约本站的任何展览门票。\n\n票款原路返回：退款申请审核通过后，票款将在 1-5 个工作日内原路退回至您的支付账户。\n\n提笔执墨，落暮皆情。 愿这场“繁华落尽，墨润浮生”的清代文人生活展，能让您在流连驻足间，读懂属于中国文人灵魂深处的浪漫与优雅。上海博物馆期待您的光临！', 500, 'http://localhost:8080/files/7900aed2-46d8-46b0-aaec-a0a6cd35777f.png', '[{\"name\":\"成人票\",\"price\":10},{\"name\":\"学生票\",\"price\":5},{\"name\":\"儿童票\",\"price\":0},{\"name\":\"社会福利票\",\"price\":0}]');
INSERT INTO `exhibition_application` VALUES (54, 2, '测试展览', '测试展览', '河北博物馆', '2026-05-26', '2026-05-31', '1', 1, '策展方确认办展，系统自动通过', '2026-05-26 18:31:28', '2026-05-26 18:30:42', '[{\"name\":\"全天\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":500}]', 0.00, '请按时入场。', 500, 'http://localhost:8080/files/d2d07a10-6343-49d1-8f99-b64bc6485ab0.jpg', '[{\"name\":\"成人票\",\"price\":10},{\"name\":\"学生票\",\"price\":5}]');

-- ----------------------------
-- Table structure for exhibition_artifact_rel
-- ----------------------------
DROP TABLE IF EXISTS `exhibition_artifact_rel`;
CREATE TABLE `exhibition_artifact_rel`  (
  `rel_id` bigint NOT NULL AUTO_INCREMENT,
  `exhibition_id` bigint NOT NULL,
  `artifact_id` bigint NOT NULL,
  PRIMARY KEY (`rel_id`) USING BTREE,
  INDEX `exhibition_id`(`exhibition_id` ASC) USING BTREE,
  INDEX `artifact_id`(`artifact_id` ASC) USING BTREE,
  CONSTRAINT `exhibition_artifact_rel_ibfk_1` FOREIGN KEY (`exhibition_id`) REFERENCES `exhibition_plan` (`exhibition_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `exhibition_artifact_rel_ibfk_2` FOREIGN KEY (`artifact_id`) REFERENCES `artifact` (`artifact_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '巡展与文物关联中间表' ROW_FORMAT = Dynamic;

