-- ----------------------------
-- Table structure for exhibition_plan
-- ----------------------------
DROP TABLE IF EXISTS `exhibition_plan`;
CREATE TABLE `exhibition_plan`  (
  `exhibition_id` bigint NOT NULL AUTO_INCREMENT COMMENT '巡展ID',
  `app_id` bigint NULL DEFAULT NULL COMMENT '来源申请ID',
  `title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '巡展名称',
  `cover_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '宣传封面图',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '巡展具体地点',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `max_capacity` int NULL DEFAULT 100 COMMENT '每日最大预约人数',
  `current_status` tinyint NULL DEFAULT 0 COMMENT '巡展状态: 0-计划中, 1-进行中, 2-已结束',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '发布详情/公告内容',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `time_slot_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '{\"09:00-12:00\": 100, \"12:00-17:00\": 100}' COMMENT '场次名额配置',
  `ticket_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '票价',
  `booking_notice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '预约须知',
  `audit_remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批备注',
  `ticket_types` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `rich_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '富文本展览介绍',
  PRIMARY KEY (`exhibition_id`) USING BTREE,
  INDEX `app_id`(`app_id` ASC) USING BTREE,
  CONSTRAINT `exhibition_plan_ibfk_1` FOREIGN KEY (`app_id`) REFERENCES `exhibition_application` (`app_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '巡展计划发布表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of exhibition_plan
-- ----------------------------
INSERT INTO `exhibition_plan` VALUES (45, 50, '【河北博物馆】青铜器展览', 'http://localhost:8080/files/90621519-bcf1-43d8-b790-5bd00be323d6.png', '河北博物馆东馆二楼', '2026-05-25 09:00:00', '2026-06-30 18:00:00', 500, 1, '绝无仅有的“国宝级”重器扎堆，国之重器密集度极高。', '2026-05-25 19:47:50', '[{\"name\":\"全天\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":500}]', 0.00, '为你整理好了一份适用于河北博物馆（官方微信小程序、售票官网、或展厅入口公示牌）的游客须知与购票/退票守则。\n\n你可以直接将以下内容配置到你的系统前端或公告模块中：\n\n🏛️ 河北博物馆 · 观众入馆须知与票务守则\n一、 💡 观展注意事项\n实名预约入馆：所有观众（含免费及优惠对象）均需提前通过官方渠道进行实名预约，携带二代身份证原件或预约二维码刷闸机入馆。\n\n保持文明静谧：展厅内请勿大声喧哗、追逐打闹；请将手机调至静音或震动模式，以免影响他人观展。\n\n严禁拍照闪光：基于文物保护要求，全馆展厅内禁止使用闪光灯、三脚架和自拍杆。\n\n衣冠整洁入场：酗酒者、衣冠不整者（如穿拖鞋、赤膊等）以及携带宠物者谢绝入馆。\n\n幼童看护原则：行动不便的老年人、残疾人以及学龄前儿童，须由成年人陪同看护入馆。\n\n二、 🚫 禁止携带物品清单（严禁带入展厅）\n为保障文物安全与公共安全，以下物品禁止带入馆内：\n\n管制及危险物品：枪支弹药、管制刀具、易燃易爆品、剧毒及放射性物品。\n\n大件行李及工具：体积超过 40×40 厘米 的大件行李箱/包（请先至寄存处寄存）、各类滑板车、平衡车。\n\n液体与食品：易污染展厅环境的各类有色饮料、黏性食品、生鲜物品。\n\n专业摄录设备：未获馆方许可的专业航拍无人机、商业摄影轨道。\n\n三、 🎟️ 社会福利票（特惠票）购买专属资格\n⚠️ 郑重提示：社会福利票（特惠/免费票）为国家定向福利，仅限以下特定人群预约或购买。入馆时须由本人同时出示身份证和有效福利证件进行双重核验：\n\n军人及优抚对象：现役军人、残疾军人、退役军人、烈士遗属、因公牺牲军人遗属、病故军人遗属（凭军官证、文职干部证、士兵证或退役军人优待证）。\n\n老年人：年满 60周岁 及以上的老年人（凭二代身份证、老年人优待证）。\n\n残疾人：持有中国残疾人联合会颁发的残疾证、伤残国家机关工作人员证者（凭残疾证原件）。\n\n※ 不符合上述条件者若误购、冒购此类票种，现场核验不予通过，将无法入馆。\n\n四、 🔄 退票规则与说明\n线上自主退票：在未检票出行的前提下，观众最晚可在预约当天闭馆前（如16:30前）通过原购买渠道申请无条件全额退票。\n\n逾期不可退改：超过预约当天闭馆时间、或门票已被核销检票的，系统将自动锁单，一律不予退改、不予退款。\n\n爽约惩罚机制：如因个人原因无法到馆且未及时在线上取消预约，累计爽约达到一定次数（如 3 次）的账户，系统将在接下来的一段时间内（如 30 天内）限制其继续预约。\n\n原路退款时效：退款申请审核通过后，票款将在 1-5 个工作日内 自动原路退回至您的支付账户（微信/支付宝/银行卡）。', NULL, NULL, '<h2 class=\"ql-align-center\"><strong>前言：铸鼎铭百越 —— 广东省博物馆馆藏青铜重器巡展</strong></h2><p>		青铜，是定格中华文明早期记忆的金色年华。当我们提起青铜器，脑海中往往会浮现出中原礼乐文明的厚重与肃穆。然而，在烟雨江南的另一端，古老的岭南大地同样在烈火与铜汁的交融中，激荡出独属于百越先民的传奇篇章。</p><p>		本次巡展由我馆与广东省博物馆联合举办，精心遴选了四件跨越春秋至东汉时期的岭南青铜瑰宝。这是一场跨越千里的文化赴约，更是一次中原礼乐风尚与百越浪漫图腾的跨时空对话。</p><p><br></p><p class=\"ql-align-center\"><strong><img src=\"http://localhost:8080/files/3d4cf879-ceab-4215-a3bb-62fd3998ec86.gif\"></strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><strong>将展览通过四个章节，为您揭开岭南青铜文明的神秘面纱</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\"><strong style=\"color: rgb(102, 102, 0);\">「春秋楚王孙铜钟」</strong></h2><p class=\"ql-align-center\">这里有<strong>「春秋楚王孙铜钟」</strong>。它承载着中原楚文化的浸润，合瓦形的钟体与庄严的铭文交织，诉说着先秦时期南北文化在礼乐规制上的碰撞与双向奔赴。</p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\"><strong style=\"color: rgb(102, 102, 0);\">「战国翼兽形铜盉」</strong></h2><p class=\"ql-align-center\">这里有<strong>「战国翼兽形铜盉」</strong>。奇幻流美的异兽双翼大展，线条流畅舒展，它将巧夺天工的造型艺术与实用的调酒功能完美融合，堪称楚风越韵工艺巅峰的代表之作。</p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\"><strong style=\"color: rgb(102, 102, 0);\">「东周青铜人首柱形器」</strong></h2><p class=\"ql-align-center\">这里有<strong>「东周青铜人首柱形器」</strong>。作为岭南考古发掘的独家物证，顶端伫立的人首保留了古老百越民族独特的五官面貌，让两千多年前那群临江赶海、断发文身的先民形象，跨越历史长河，鲜活地跃然于观者眼前。</p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\"><strong style=\"color: rgb(102, 102, 0);\">「东汉四蛙乘骑像铜鼓」</strong></h2><p>这里更有<strong>「东汉四蛙乘骑像铜鼓」</strong>。作为南方青铜文化的最高代表，鼓面边缘栩栩如生的青蛙与乘骑塑像，生动再现了百越先民祈求风调雨顺、稻作丰收的求雨祭祀场景，彰显着浓郁的图腾崇拜与独特的南方黑科技。</p><p><br></p><p><br></p><p>鼎铸岭南，墨绘百越。这批来自广东省博物馆的青铜重器，不仅打破了文物冰冷的玻璃罩，更用它们斑驳的锈迹与精绝的纹饰，向我们昭示着中华文明多元一体的宏大包容。提笔执墨，落暮皆情。让我们一同走进这片由青铜铸就的战国雄风与大汉幽州，去聆听那段激荡在南岭以南的远古回响。</p>');
INSERT INTO `exhibition_plan` VALUES (46, 51, '【广东博物馆】越海流徽：岭南历代法书墨迹展', 'http://localhost:8080/files/e3f440de-924c-4efe-ab8a-a8c503e099b7.png', '广东博物馆A馆', '2026-05-25 09:00:00', '2026-06-30 18:00:00', 1000, 1, '“越海”代指古百越与南海丝路，地理特征明显；“流徽”语出古诗文，意为流传下来的美德、诗文或艺术光彩。名字温润高雅。', '2026-05-25 20:10:12', '[{\"name\":\"上午入场\",\"timeRange\":[\"09:00\",\"12:00\"],\"quota\":400},{\"name\":\"下午入场\",\"timeRange\":[\"13:00\",\"18:00\"],\"quota\":600}]', 0.00, '特价票预约与购票须知\n⚠️ 【严正提示】\n本馆社会福利票（特价/免票）属国家定向福利，仅限特定符合条件的人群预约及购买。\n为确保文物安全与入馆秩序，本馆实行**“实名预约+现场双重核验”**制。非符合条件人员请勿错购、冒购，否则现场核验不予通过将无法入馆。\n一、 专属购票与预约资格\n只有符合以下条件的观众，方可预约或购买社会福利票，入馆时须由本人出示二代身份证原件及对应的有效福利证件：\n老年人群\n资格条件：年满 60周岁 及以上的老年人。\n核验证件：本人二代身份证 或 老年人优待证原件。\n残疾人群\n资格条件：持有中国残疾人联合会颁发的残疾证，或伤残国家机关工作人员。\n核验证件：本人有效残疾证原件 或 伤残国家机关工作人员证原件。\n军人及优抚对象\n资格条件：现役军人、残疾军人、退役军人，以及烈士遗属、因公牺牲军人遗属、病故军人遗属。\n核验证件：本人军官证、文职干部证、士兵证、学员证或退役军人优待证原件。\n\n二、 现场核验与入馆流程\n实名比对：入馆时需在专设的“绿色通道/福利核验窗口”排队，由工作人员进行人脸、身份证及物理证件的三合一比对。\n\n证件有效性：所有福利证件必须在有效期内，涂改、过期、伪造或照片模糊不清的证件一律视为无效。\n\n禁止代刷：福利票限本人使用，严禁冒用、代刷他人证件。一经发现，馆方有权谢绝入馆并依法暂扣冒用证件。\n\n三、 退票与改签规则\n自主退票时限：在未检票入馆的前提下，如因行程变动，观众最晚可在预约当天闭馆前（如16:30前）通过原购买渠道申请线上全额退票。\n\n逾期锁单不退：超过预约当天闭馆时间，或门票已被现场扫描核销的，系统将自动锁单，一律不予退改、不予退款。\n\n爽约惩罚机制：若成功预约福利票后未到馆，且未在规定时间内取消，累计爽约满 3 次的账户，系统将自动触发限制机制，在接下来的 30天内 将无法再次预约本馆的任何门票。\n退款原路返回：线上申请退款成功后，系统将在 1-5 个工作日内 将票款原路退回至您的支付账户（微信/支付宝/银行卡）。', NULL, NULL, '<h1 class=\"ql-align-center\"><strong style=\"color: rgb(0, 138, 0);\">越海流徽 —— 广东省博物馆与上海博物馆法书联合巡展</strong></h1><p><br></p><p>		翰墨千载，不过是墨汁落入宣纸时的一声轻叹；气象万千，皆定格于狼毫游走绢素时的提按顿挫。中国书法，从来不仅是线条的罗列，它是历代文人的铮铮风骨，是孤灯夜长时的自我剖白，更是生命在岁月激荡中留下的物化年轮。当纸墨相发，那些流传百代的笔尖微澜，便化作了打破时空界限的旷世绝响。</p><p>		本次巡展由我馆联合广东省博物馆与上海博物馆倾情奉献。展览以“传世·承袭·交融”为不竭之思，精心遴选了两大博物馆馆藏中最具分量、堪称中国书法史里程碑的三件法书瑰宝。这是一场跨越地域的文化交响，更是一次晋唐神韵与宋代尚意书风在方寸之间的巅峰对话。</p><p class=\"ql-align-center\"><img src=\"http://localhost:8080/files/de382230-54e3-45fc-a550-5e900b8c3e10.png\"></p><h4 class=\"ql-align-center\"><br></h4><h4 class=\"ql-align-center\"><a href=\"http://localhost:5173/user/relic-detail/104\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>【卷一·曲水流觞】 广东省博物馆藏 —— 《兰亭集序（神龙本）》</strong></a></h4><p class=\"ql-align-center\">那是东晋永和九年的暮春之初，会稽山阴的茂林修竹间，天朗气清，惠风和畅。书圣王羲之微醺提笔，一气呵成。本展展出的《兰亭集序（神龙本）》，虽为后世依真迹精摹之本，却因其带有神龙半印而名冠天下。它极其完美地保留了“天下第一行书”神妙飘逸、遒媚内敛的原始笔意。乾坤燥润、浓淡枯荣间，无一字不妥帖，无一笔不流美。那些深浅不一的墨痕，至今仍散发着魏晋名士放浪形骸、崇尚自然的绝代风流，是后世书者遥望中国行书源头的无上精神坐标。</p><p class=\"ql-align-center\"><img src=\"http://localhost:8080/files/c0e722b1-3516-4f60-bcb1-7182248c5ad7.png\"></p><h4 class=\"ql-align-center\"><br></h4><h4 class=\"ql-align-center\"><a href=\"http://localhost:5173/user/relic-detail/133\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>【卷二·险绝风骨】 上海博物馆藏 —— 《松风阁（摹本）》</strong></a></h4><p class=\"ql-align-center\">视线北上，掠过千山烟水，落笔处已是北宋文人的尚意江湖。原作乃北宋巨匠黄庭坚晚年寓居鄂州樊山松风阁时，听松涛阵阵、忆平生挚友而写下的行书绝笔。此本精摹本精准捕获了山谷道人“以画入书”的核心神髓。画面中字形中宫紧收、四面辐射，长笔纵横，如长枪大戟般极具奇崛之险。其线条沉雄郁拔，转折处如斩钉截铁，将北宋文人那种身处逆境却依然傲骨嶙峋、独步天下的精神世界，展现得淋漓尽致。</p><p class=\"ql-align-center\"><img src=\"http://localhost:8080/files/4da6d9c9-893a-4978-ba61-b48bbbda5314.png\"></p><h4 class=\"ql-align-center\"><br></h4><h4 class=\"ql-align-center\"><a href=\"http://localhost:5173/user/relic-detail/135\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>【卷三·文心雕墨】 上海博物馆藏 —— 北宋《千字文卷》</strong></a></h4><p class=\"ql-align-center\">天地玄黄，宇宙洪荒。同为上海博物馆珍藏的北宋《千字文卷》，则向我们展示了古典法度的极致之美。全卷上千字一气呵成，行笔如行云流水，结构严谨而气势连贯。它在法度中见飘逸，在规整中显灵动，每一个结字都仿佛经过千锤百炼，却又毫无人工雕琢的刻意。千字交织，墨气淋漓，这不仅是对华夏启蒙经典的至高致敬，更是宋代书者将古典主义美学推向极致的历史见证。</p><p class=\"ql-align-center\"><img src=\"http://localhost:8080/files/320ed2be-6232-4c42-9c98-fd3afebbf1ee.jpg\"></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><img src=\"http://localhost:8080/files/ec505591-396f-44cd-95b7-aa5500ac1dfa.png\"></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\">纸寿千年，墨润万物。这批跨越千里、在南粤大地集结亮相的传世法书真迹与精摹臻品，不仅打破了博物馆冰冷的玻璃罩，更用它们斑驳的绢素与遒劲的线条，向我们昭示着中华书法文明一脉相承、生生不息的血脉力量。</p><p class=\"ql-align-center\">提笔执墨，落暮皆情。在这座由翰墨铸就的纸上森林里，每一位观者都是时间的旅人。愿您在流连驻足间，能听懂那段回响在宣纸之上的远古心跳，读懂属于中国文人灵魂深处的浪漫与优雅。</p><p><br></p><h3 class=\"ql-align-center\"><strong>【广东博物馆宣发】越海流徽：岭南历代法书墨迹展周边领取指南</strong></h3><p>		翰墨飘香，流徽千年。广东省博物馆年度法书大展「越海流徽：岭南历代法书墨迹展」正在火热展出中！从陈白沙苍劲生辣的茅龙笔草书，到传世重器的晋唐墨迹神韵，一幅幅法书珍品让无数观众流连忘返。</p><p>为了让这份属于文人的浪漫与优雅走进大家的日常生活，馆方特别推出了本场展览的<strong>限定独家文创周边</strong>。如何将这些高颜值、充满书卷气的限定周边带回家？这份【周边领取指南】请务必收好！</p><p><br></p><h3><strong>✨ 一、 展览限定周边抢先看</strong></h3><ol><li><strong>【兰亭曲水】限定透卡</strong>：以展出法书的经典笔意为灵感，结合岭南山水设计的半透明书签透卡，阳光下折射出淡淡的墨香。</li><li><strong>【白沙遗风】茅龙贴纸</strong>：提取陈白沙标志性“茅龙体”狂草字迹，极具视觉冲击力，可贴于手帐本、电脑或手机壳上。</li><li><strong>【墨染五岭】定制帆布袋</strong>：大容量厚质帆布，正面印有展览主题“越海流徽”的专属大印与水墨泼墨山水图，文艺出街必备。</li></ol><p><br></p><h3><strong>🎁 二、 周边免费领取攻略（三选一或兼得）</strong></h3><h4><strong>攻略【1】—— 微信打卡有礼（可得：限定透卡）</strong></h4><ul><li><strong>参与方式</strong>：在展厅内寻找你最喜欢的一幅法书作品，拍照并分享至朋友圈。</li><li><strong>配文要求</strong>：带话题 <strong>#广东省博物馆越海流徽大展#</strong>，并附上一句你的观展心得。</li><li><strong>领取地点</strong>：三层历代书画展厅出口处的【文创服务台】。</li><li><strong>核验方式</strong>：向现场工作人员出示手机发布界面，即可现场兑换。</li></ul><h4><strong>攻略【2】—— 盖章集赞挑战（可得：茅龙贴纸）</strong></h4><ul><li><strong>参与方式</strong>：在展厅入口处免费领取“越海流徽”专用集章小册子，在展厅内的三个打卡点成功盖上本次展览的限定大印。</li><li><strong>领取地点</strong>：一层大堂【服务中心】。</li><li><strong>核验方式</strong>：出示集满三个印章的小册子即可兑换，同时你的小册子也可以带回家留作纪念。</li></ul><h4><strong>攻略【3】—— 现场互动问答（可得：定制帆布袋 · 每日限量）</strong></h4><ul><li><strong>参与方式</strong>：每日上午 10:00 及下午 15:00，展厅内将举办短暂的“法书小知识”现场互动，只要答对导览员提出的关于“兰亭集序”或“岭南书法”的趣味小问题，即可直接获得。</li><li><strong>领取地点</strong>：互动现场直接发放。</li></ul><p><img src=\"http://localhost:8080/files/f698764a-7417-4a51-9e52-dabd8a1649d2.png\"></p><h3><strong>⚠️ 三、 周边领取核心注意事项</strong></h3><ol><li><strong>实名核销原则</strong>：为让更多观众体验福利，每名观众凭当天有效的入馆预约码（二代身份证），每种周边<strong>限领一份</strong>，不可代领。</li><li><strong>数量有限，先到先得</strong>：所有限定周边均为本场展览专属定制，<strong>每日限量发放</strong>。如当日发放完毕，相关打卡活动将自动顺延至次日。</li><li><strong>特价票/社会福利票观众专享绿色通道</strong>：凡持有老年证、军官证、残疾证并购买/预约了社会福利票的观众，可在【文创服务台】直接免打卡领取【限定透卡】一张。</li><li><strong>保持展厅秩序</strong>：请在打卡拍照、排队领周边的过程中保持安静，切勿大声喧哗，听从现场工作人员的指引，共同维护高雅的观展环境。</li></ol><p><strong>提笔执墨，落暮皆情。</strong> 愿这些精致的周边能成为您本次广博之行的美好延伸。我们在展厅里，静候您的到来，一同读懂属于中国文人灵魂深处的优雅。</p>');
INSERT INTO `exhibition_plan` VALUES (47, 52, '【上海博物馆】繁华落尽，墨润浮生：清代文人生活展', 'http://localhost:8080/files/7900aed2-46d8-46b0-aaec-a0a6cd35777f.png', '上海博物馆西馆二楼西区', '2026-05-25 09:00:00', '2026-06-30 18:00:00', 500, 1, '摒弃了宏大的政治叙事，将视角对准清代文人的内心世界与精致的日常生活。“案头清供”指书房里的玉雕、墨砚、文具，给人一种“结庐在人境，心远地自偏”的优雅与静谧。', '2026-05-25 21:26:37', '[{\"name\":\"上午场次\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":500},{\"name\":\"下午场次\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":0},{\"name\":\"\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":0}]', 0.00, '【上海博物馆】“繁华落尽，墨润浮生：清代文人生活展”参观须知\n摒弃了宏大的政治叙事，本次展览将视角精准对准清代文人的内心世界与精致的日常生活。从书房里的玉雕、墨砚，到几案前的文具清供，无不传递着“结庐在人境，心远地自偏”的优雅与静谧。\n\n为了给您营造一个高雅、安静且秩序井然的观展环境，更好地体味清代文人的墨润浮生，请在购票及入馆前仔细阅读以下参观须知：\n\n一、 🎟️ 票务配置与预约说明\n本展览实行全员实名制分时段预约，观众需根据自身条件选择对应票种并合理安排场次：\n\n成人票：适用于普通成年观众。\n\n学生票 / 儿童票：适用于在校学生及未成年儿童，入场时需核验相关学生证件。\n\n老年票 / 社会福利票（特惠免票）：\n\n老年票：限60周岁及以上老年人预约。\n\n社会福利票：仅限现役军人、残疾军人、退役军人、残疾人等国家定向福利群体预约。\n\n⚠️ 特别提示：购买老年票与社会福利票的观众，入馆时须由本人同时出示二代身份证原件和对应的有效福利证件（如残疾证、军官证、退役军人优待证等）进行现场双重核验。非符合条件人员请勿错购，否则核验不予通过将无法入馆。\n\n二、 ⏰ 场次管理与入馆时限\n上午场：入馆及检票时间为 09:00 - 13:00（请在对应时段内刷闸机进馆，错开高峰）。\n\n下午场：入馆及检票时间为 13:00 - 17:00（每日17:00停止检票入馆）。\n\n请严格按照您预约的场次时间前来参观。因个人原因迟到或错过对应场次，当日门票将自动失效。\n\n三、 🚫 展厅内禁止携带物品及行为规范\n文人书房，重在静谧与雅致。为保护传世书画、漆器及玉石器等脆弱文物，请遵守以下规定：\n\n严禁拍照闪光：展厅内严禁使用闪光灯、三脚架及自拍杆。强光和金属支架极易对古代书画和漆器造成不可逆的物理损伤。\n\n禁止携带大件物品：体积超过 40×40 厘米的行李箱、背包，以及滑板车等工具请先至寄存处寄存。\n\n严禁携带食品饮料：请勿将有色饮料、黏性食品、生鲜及宠物带入展厅，共同维护展厅的清洁环境。\n\n保持展厅静谧：请将手机调至静音或震动模式。展厅内请勿大声喧哗、追逐打闹，以免惊扰清代文人的“案头清供”之美。\n\n四、 🔄 退票与爽约规则\n无忧退票时限：在未检票入馆的前提下，如行程有变，最晚可在预约当天闭馆前（16:30前）通过系统原渠道申请线上全额退票。\n\n逾期锁单不退：超过预约当天闭馆时间，或门票已被核销检票的，系统将自动锁单，一律不予退改。\n\n爽约惩罚机制：若成功预约门票（含免费福利票）后未到馆参观，且未在规定时间内取消，累计爽约满 3 次的账户，系统将自动限制其在接下来的 30天内 再次预约本站的任何展览门票。\n\n票款原路返回：退款申请审核通过后，票款将在 1-5 个工作日内原路退回至您的支付账户。\n\n提笔执墨，落暮皆情。 愿这场“繁华落尽，墨润浮生”的清代文人生活展，能让您在流连驻足间，读懂属于中国文人灵魂深处的浪漫与优雅。上海博物馆期待您的光临！', NULL, NULL, '<h1 class=\"ql-align-center\"><strong style=\"color: rgb(178, 107, 0); background-color: rgb(255, 235, 204);\">横向美学重组：清代文人生活的“三重宿命”</strong></h1><p><br></p><h2 class=\"ql-align-center\"><strong style=\"color: rgb(0, 55, 0);\">第一重：繁华的枷锁 —— 簪缨与海市的世俗皮囊</strong></h2><p>		清代文人的底色，首先是世俗的、繁华的。在康乾盛世的晚期，手工业与海上贸易达到了中国古代的最高峰。文人们身处其中，他们的家庭与生活被一种极致的、甚至略带奢靡的物质审美所包裹。</p><p><img src=\"http://localhost:8080/files/a7471821-f0f6-4aa7-ba9a-94022c267af9.png\"></p><ul><li><strong>【上海博物馆 · 点翠镶嵌红蓝宝石如意簪】</strong>：它是文人家庭闺阁中最夺目的亮色。翠羽的幽蓝与宝石的火红交织，不仅是财富的彰显，更是江南世家对细节品质近乎偏执的考究。</li><li><strong>【河北博物馆 · 刺绣八仙过海图条屏】与【上海博物馆 · 红地缂丝百子迎春图挂轴】</strong>：这两件织物，一件带着北方燕赵大地的硬朗与神仙寄托，一件带着南方织造“通经断纬”的绵密与家族期盼。红底百子，八仙凌波，文人的厅堂被这种极其热闹、极其世俗的祥瑞之气填满。</li><li><strong>【广东省博物馆 · 外销银累丝寿字纹香熏】</strong>：当一缕异香从累丝缝隙中飘出，它曾跨越伶仃洋，见证了一口通商的十三行风云。这是文人生活在“全球化”海贸浪潮下的一个缩影——他们的肉身，被牢牢锁在这场中国古代手工业最后的饕餮盛宴里。</li><li><br></li></ul><h2 class=\"ql-align-center\"><strong style=\"color: rgb(0, 55, 0);\">第二重：墨润的避难所 —— 书斋里对抗风雨的微观世界</strong></h2><p>		然而，文字狱的酷烈与仕途的险恶，让这群敏锐的灵魂感到窒息。于是，他们把目光从宏大的朝堂，收缩进了一方小小的书斋。在“案头清供”的微观世界里，他们开始了一场精神的自救。</p><p><img src=\"http://localhost:8080/files/f6357738-6632-4042-b15d-ecd2f65dcae0.png\"></p><ul><li><strong>【河北博物馆 · 黑漆螺钿山水亭台纹文具箱】</strong>：黑漆如夜，螺钿如星。文人把一开一合的箱箧，当成自己收纳笔墨的方寸天地。外界风雨大作，书斋内唯有文具玲珑。他们在这里整理纸墨，其实是在收拾自己被世俗撞得细碎的心。</li><li><strong>【广东省博物馆 · 清端石千岩竞秀砚】</strong>：这是书斋里最核心的圣物。匠人随形施艺，在端石上雕琢出层峦叠嶂。文人在晨光中磨墨，手指触碰着那微凉的石质，砚上的“千岩竞秀”，不是远方的风景，而是他们无法在现实中实现的胸中丘壑。墨润笔端，他们在一砚一墨的清供中，守住了自己最后的清高与优雅。</li><li><br></li></ul><h2 class=\"ql-align-center\"><strong style=\"color: rgb(0, 55, 0);\">第三重：金石的自救 —— 在斑驳的古文字里寻找不朽</strong></h2><p>		当现实的繁华终将“落尽”，肉身必将腐朽，清代文人最终在历史的深处找到了他们的归宿——那就是金石碑学。他们不再迷恋当下的功名，转而向一千多年前的石头和青铜寻找生命的永恒。</p><p><img src=\"http://localhost:8080/files/8ec7ccb9-3572-4848-be22-b1aa14de0d1f.png\"></p><ul><li><strong>【上海博物馆 · 清拓汉张迁碑册】</strong>：汉隶的方整、厚重与拙朴，在这册拓本上留下了斑驳的墨痕。清代文人推崇碑学，他们借着微弱的油灯，一遍遍摹写着《张迁碑》那斩钉截铁的线条。在一生无数次的提按顿挫中，汉隶的法度转化为了他们的心理防御机制。繁华落尽，唯有这些刻在石头上、传于宣纸之上的文字，能够跨越生死，墨润浮生。</li></ul><p><br></p><p><br></p><h1>【繁华落尽 · 展览限定文创及周边雅集指南】</h1><p>		物质的繁华虽会落尽，但那些承载过文人灵魂的笔触与风骨，却能借由当代的设计重获新生。上海博物馆联合多方设计团队，将展厅中清代文人的精神世界，凝练为四款兼具日常实用与古典美学的限定文创。愿您在观展之余，亦能将这份“墨润浮生”的优雅带回日常生活。<img src=\"http://localhost:8080/files/640a519f-aebf-4d3b-8791-298d8711116e.png\"></p><h2>一、限定周边 · 免费领取攻略</h2><p>本板块周边为非卖品，需通过观展过程中的“文人体验”互动或特定票种福利获取。</p><h3>🦚 【笔底波澜】点翠美学 · 限定帆布袋</h3><ul><li><strong>美学蓝本</strong>：灵感源自上博馆藏《点翠镶嵌红蓝宝石如意簪》<strong>与河北博物馆藏</strong>《刺绣八仙过海图条屏》。</li><li><strong>设计巧思</strong>：大容量的原色厚质帆布袋上，将点翠那抹夺目的幽蓝与刺绣的五彩丝线，以高精度的数码泼墨工艺晕染开来。世俗的极致繁华在布料上“落尽”为抽象的山水波澜，高级且富有张力，是文艺出街的绝佳单品。</li><li><strong>获取方式【数字裂变打卡】</strong>：</li><li class=\"ql-indent-1\"><strong>浮生共鸣</strong>：在展厅内任选一处让您感触最深的文玩（如端砚或文具箱），拍照并分享至个人社交平台。</li><li class=\"ql-indent-1\"><strong>配文要求</strong>：带话题 <strong>#上博清代文人生活展#</strong> 并附上您对“繁华落尽，墨润浮生”的一句随笔感悟。</li><li class=\"ql-indent-1\"><strong>核销地点</strong>：一楼大堂服务中心（每人凭当日有效预约入馆码限领一个，每日限额，先到先得）。</li><li><strong>【特定票种与绿色通道】</strong>：</li><li class=\"ql-indent-1\"><strong>福利专享</strong>：凡持老年证、军官证、残疾证并预约<strong>社会福利票 / 老年票</strong>的观众，可在入馆时于绿色通道核验处，直接凭本人有效证件免任务免费领取一个，数量有限，先到先得。</li></ul><h2>二、：限定文创 · 倾心选购指南（案头清供）</h2><p>本板块周边为上海博物馆官方文创旗舰店、线上商城同步发售的清代文人生活美学重器。</p><p><br></p><h3>🧢 【金石骨气】汉隶张迁碑 · 刺绣棒球帽</h3><ul><li><strong>美学蓝本</strong>：视觉解构上海博物馆藏《清拓汉张迁碑册》。</li><li><strong>设计巧思</strong>：放弃了死板的全文印制，设计师仅截取了《张迁碑》中方整雄强、极具现代骨骼感的标志性汉隶笔触，以沉稳的黑白两色丝线，立体刺绣于复古棉质棒球帽上。低调、硬朗，戴上它，是将千年金石的傲骨顶在头上。</li><li><strong>获取方式：</strong>上海博物馆一楼【官方文宣旗舰店】/ 本站商城</li></ul><p><br></p><h3>🧥 【浮生墨白】清代山水 · 浮雕印花文化衫</h3><ul><li><strong>美学蓝本</strong>：融合广东省博物馆藏《清·端石千岩竞秀砚》的墨堂意境。</li><li><strong>设计巧思</strong>：选用高克重重装纯棉面料，通体呈现深邃的墨黑色与宣纸的米白色。胸前采用发泡浮雕工艺，将端砚上那幅“千岩竞秀”的重峦叠嶂以微立体的方式还原。摸上去如同砚石的肌理，穿在身上，便是将胸中的丘壑与山水化为了当代的时尚战袍。</li><li><strong>选购地点</strong>：上海博物馆一楼【官方文宣旗舰店】/ 本站商城。</li></ul><p><br></p><h3>🖋️ 【书斋自救】黑漆螺钿 · 限量笔记本钢笔组合</h3><ul><li><strong>美学蓝本</strong>：1:1 视觉解构河北博物馆藏《清·黑漆螺钿山水亭台纹文具箱》。</li><li><strong>设计巧思</strong>：这是本场大展的终极工艺文创。</li><li class=\"ql-indent-1\"><strong>笔记本</strong>：封面采用特殊钢琴烤漆材质，黑漆如夜，并在其上运用贝壳纸拼嵌出极为精细的螺钿山水亭台纹饰；</li><li class=\"ql-indent-1\"><strong>钢笔</strong>：笔身同样点缀螺钿流光，搭配定制的定制金尖，阻尼感完美复刻宣纸书写体验。</li><li class=\"ql-indent-1\">笔墨纸砚，在一开一合的礼盒间，为您在当代的办公桌上，筑起一方用来对抗浮躁、整理心绪的“微观避难所”。</li><li><strong>选购地点</strong>：上海博物馆一楼【官方文宣旗舰店】/ 本站商城。</li></ul><p><br></p><p><br></p><h2>⚠️ <span style=\"color: rgb(230, 0, 0);\">三、观展与周边领取核心守则</span></h2><p>为保障文物安全与高雅的观展秩序，请所有前来领取/购买周边的观众务必遵守：</p><p><br></p><ol><li><strong>时段对应核销</strong>：周边领取严格与您的预约场次挂钩。上午场（09:00 - 13:00）预约观众请勿在下午场前来排队领取，系统无法跨场次读取预约码。</li><li><strong>严格证件比对</strong>：由于【金石棒球帽】属于社会福利票/老年票觀眾的直接免打卡福利，现场将严格执行“人脸+身份证+物理证件（如残疾证、军官证等）”三合一比对，严禁代刷、冒用他人证件。</li><li><strong>退票熔断机制</strong>：如您在未检票前申请了线上退票，您的周边预约资格将同步注销。所有限定周边均为每日限量发放，如遇当日库存熔断，相关线上打卡活动将自动顺延至次日。</li><li><strong>守序即是高雅</strong>：文人书斋，重在静谧。在打卡拍照、排队或购买文化衫、笔记本的过程中，请勿大声喧哗、争抢。请听从馆方工作人员的现场指引，将您的脚步，放轻在清代文人的墨润时光里。</li></ol><p><br></p><p><br></p>');
INSERT INTO `exhibition_plan` VALUES (49, 54, '测试展览', 'http://localhost:8080/files/d2d07a10-6343-49d1-8f99-b64bc6485ab0.jpg', '河北博物馆', '2026-05-26 09:00:00', '2026-05-31 18:00:00', 500, 1, '测试展览', '2026-05-26 18:31:28', '[{\"name\":\"全天\",\"timeRange\":[\"09:00\",\"18:00\"],\"quota\":500}]', 0.00, '请按时入场。', NULL, NULL, '<p><strong>测试展览。</strong></p>');

-- ----------------------------
-- Table structure for favorite
-- ----------------------------
DROP TABLE IF EXISTS `favorite`;
CREATE TABLE `favorite`  (
  `fav_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `exhibition_id` bigint NOT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`fav_id`) USING BTREE,
  UNIQUE INDEX `user_id`(`user_id` ASC, `exhibition_id` ASC) USING BTREE,
  INDEX `exhibition_id`(`exhibition_id` ASC) USING BTREE,
  CONSTRAINT `favorite_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `favorite_ibfk_2` FOREIGN KEY (`exhibition_id`) REFERENCES `exhibition_plan` (`exhibition_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '巡展收藏表' ROW_FORMAT = Dynamic;

