-- Records of favorite
-- ----------------------------
INSERT INTO `favorite` VALUES (31, 1, 45, '2026-05-25 19:57:39');
INSERT INTO `favorite` VALUES (32, 1, 46, '2026-05-25 20:27:25');

-- ----------------------------
-- Table structure for notice
-- ----------------------------
DROP TABLE IF EXISTS `notice`;
CREATE TABLE `notice`  (
  `notice_id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `author_id` bigint NULL DEFAULT NULL COMMENT '发布管理员ID',
  `author_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '管理员' COMMENT '发布者昵称',
  `notice_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '系统公告' COMMENT '公告类型',
  `is_top` tinyint NULL DEFAULT 0 COMMENT '是否置顶: 0-否, 1-是',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`notice_id`) USING BTREE,
  INDEX `author_id`(`author_id` ASC) USING BTREE,
  CONSTRAINT `notice_ibfk_1` FOREIGN KEY (`author_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统公告表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of notice
-- ----------------------------
INSERT INTO `notice` VALUES (8, '【河北博物馆周边文物上新】青铜器小模型，可爱上新，商城热销中！', '<h2 class=\"ql-align-center\">它们曾是庄重的礼器，在河北名窑与古墓中沉睡千年。如今，褪去岁月的肃穆，化身治愈系小模型灵动归来。 精细复刻每一道云雷纹饰，保留青铜的古拙，融入现代的可爱。 <strong>河北博物馆周边上新</strong>——不只是文创，更是触手可及的文明体温。 把“镇馆之宝”带回家，让桌面成为你的私人微缩博物馆。</h2><p class=\"ql-align-center\"><img src=\"http://localhost:8080/files/65f8e45f-d6d5-4bcf-99c2-b954081dbbcd.png\"></p><h3 class=\"ql-align-center\">谁说文物都是冷冰冰？河北博物馆青铜家族集体“成精”啦！ Q版比例 + 考究工艺，丑萌届的颜值天花板，摆在哪都是焦点。 ✅ 办公桌解压神器 ✅ 送礼不撞款的文化宝藏 ✅ 摄影摆拍的满分道具 <strong>商城热销中！</strong> 戳下方链接，开启你的“考古”寻宝之旅！</h3><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><p><br></p>', 3, '系统管理员', '活动通知', 0, '2026-05-06 01:04:25');
INSERT INTO `notice` VALUES (9, '大器同行，共纳山海 ', '<h3 class=\"ql-align-center\"><strong>大器同行，共纳山海 —— 期待您的博物馆光临入驻</strong></h3><p class=\"ql-align-center\"><br></p><p>		每一座博物馆，都是一处收藏文明碎片、封存时光心跳的宏伟殿堂。 从斑驳厚重的青铜礼乐，到流徽千载的法书墨迹，那些沉睡在展厅玻璃罩后的稀世珍宝，值得被世界以更无界、更灵动的方式看见。</p><p>为了搭建中原与岭南、古典与现代、文物与大众之间的数字桥梁，本站现面向全国各级博物馆、艺术馆及文化机构发出最诚挚的入驻邀请。</p><p>		在这里，我们不仅一同打破时空的边界，让文物在云端“活起来”；更将并肩执笔，为亿万线上的文化旅人，打造一座永不闭馆的数字博览森林。</p><p>提笔执墨，落暮皆情。我们怀揣对历史的敬畏，在此静候您的加入，一同开启华夏文明一脉相承、多元一体的数字新篇章！</p><p><br></p><h3 class=\"ql-align-center\"><strong>入驻专享权益抢先看</strong></h3><ol><li><strong>核心展讯全网宣发</strong>：尊享常设展、特展及交流巡展的专属头条推荐，直达百万博物馆爱好者。</li><li><strong>社会福利票高效预约</strong>：系统内置智能核销机制，支持老年人、残疾人及军人等特定人群的特惠/免票实名制预约与无忧退改。</li><li><strong>数字文创/周边裂变</strong>：轻松助力展厅限定周边与文创产品的火爆出圈。</li></ol><p><br></p><h3 class=\"ql-align-center\"><strong>馆际入驻联系方式</strong></h3><p>		如果您有入驻意向、展讯宣发或巡展合作需求，欢迎随时与我们取得联系。我们的工作人员将在 <strong>1-2 个工作日内</strong> 为您开通绿色通道并协助完成平台入驻：</p><ul><li><strong>官方入驻邮箱</strong>：museum_service@platform.com</li><li><strong>专属合作电话</strong>：020-1599-2888</li><li><strong>商务合作微信</strong>：museum_service2888</li><li><strong>入驻服务联络人</strong>：李经理 </li><li><strong>办公接洽地址</strong>：：北京市海淀区西二旗33号</li></ul><h3><br></h3><p><br></p><p><br></p>', 9, '站点管理员', '站点公告', 1, '2026-05-13 12:59:51');
INSERT INTO `notice` VALUES (10, '【广东博物馆宣发】越海流徽：岭南历代法书墨迹展周边领取指南', '<h3><strong>【广东博物馆宣发】越海流徽：岭南历代法书墨迹展周边领取指南</strong></h3><p>		翰墨飘香，流徽千年。广东省博物馆年度法书大展「越海流徽：岭南历代法书墨迹展」正在火热展出中！从陈白沙苍劲生辣的茅龙笔草书，到传世重器的晋唐墨迹神韵，一幅幅法书珍品让无数观众流连忘返。</p><p>为了让这份属于文人的浪漫与优雅走进大家的日常生活，馆方特别推出了本场展览的<strong>限定独家文创周边</strong>。如何将这些高颜值、充满书卷气的限定周边带回家？这份【周边领取指南】请务必收好！</p><p><br></p><h3><strong>✨ 一、 展览限定周边抢先看</strong></h3><ol><li><strong>【兰亭曲水】限定透卡</strong>：以展出法书的经典笔意为灵感，结合岭南山水设计的半透明书签透卡，阳光下折射出淡淡的墨香。</li><li><strong>【白沙遗风】茅龙贴纸</strong>：提取陈白沙标志性“茅龙体”狂草字迹，极具视觉冲击力，可贴于手帐本、电脑或手机壳上。</li><li><strong>【墨染五岭】定制帆布袋</strong>：大容量厚质帆布，正面印有展览主题“越海流徽”的专属大印与水墨泼墨山水图，文艺出街必备。</li></ol><p><br></p><h3><strong>🎁 二、 周边免费领取攻略（三选一或兼得）</strong></h3><h4><strong>攻略【1】—— 微信打卡有礼（可得：限定透卡）</strong></h4><ul><li><strong>参与方式</strong>：在展厅内寻找你最喜欢的一幅法书作品，拍照并分享至朋友圈。</li><li><strong>配文要求</strong>：带话题 <strong>#广东省博物馆越海流徽大展#</strong>，并附上一句你的观展心得。</li><li><strong>领取地点</strong>：三层历代书画展厅出口处的【文创服务台】。</li><li><strong>核验方式</strong>：向现场工作人员出示手机发布界面，即可现场兑换。</li></ul><h4><strong>攻略【2】—— 盖章集赞挑战（可得：茅龙贴纸）</strong></h4><ul><li><strong>参与方式</strong>：在展厅入口处免费领取“越海流徽”专用集章小册子，在展厅内的三个打卡点成功盖上本次展览的限定大印。</li><li><strong>领取地点</strong>：一层大堂【服务中心】。</li><li><strong>核验方式</strong>：出示集满三个印章的小册子即可兑换，同时你的小册子也可以带回家留作纪念。</li></ul><h4><strong>攻略【3】—— 现场互动问答（可得：定制帆布袋 · 每日限量）</strong></h4><ul><li><strong>参与方式</strong>：每日上午 10:00 及下午 15:00，展厅内将举办短暂的“法书小知识”现场互动，只要答对导览员提出的关于“兰亭集序”或“岭南书法”的趣味小问题，即可直接获得。</li><li><strong>领取地点</strong>：互动现场直接发放。</li></ul><p><img src=\"http://localhost:8080/files/f698764a-7417-4a51-9e52-dabd8a1649d2.png\"></p><h3><strong>⚠️ 三、 周边领取核心注意事项</strong></h3><ol><li><strong>实名核销原则</strong>：为让更多观众体验福利，每名观众凭当天有效的入馆预约码（二代身份证），每种周边<strong>限领一份</strong>，不可代领。</li><li><strong>数量有限，先到先得</strong>：所有限定周边均为本场展览专属定制，<strong>每日限量发放</strong>。如当日发放完毕，相关打卡活动将自动顺延至次日。</li><li><strong>特价票/社会福利票观众专享绿色通道</strong>：凡持有老年证、军官证、残疾证并购买/预约了社会福利票的观众，可在【文创服务台】直接免打卡领取【限定透卡】一张。</li><li><strong>保持展厅秩序</strong>：请在打卡拍照、排队领周边的过程中保持安静，切勿大声喧哗，听从现场工作人员的指引，共同维护高雅的观展环境。</li></ol><p><strong>提笔执墨，落暮皆情。</strong> 愿这些精致的周边能成为您本次广博之行的美好延伸。我们在展厅里，静候您的到来，一同读懂属于中国文人灵魂深处的优雅。</p>', 8, '广博策展人', '巡展资讯', 0, '2026-05-25 20:34:05');
INSERT INTO `notice` VALUES (11, '【上海博物馆宣发】繁华落尽 · 展览限定文创及周边雅集指南', '<h1>【繁华落尽 · 展览限定文创及周边雅集指南】</h1><p>		物质的繁华虽会落尽，但那些承载过文人灵魂的笔触与风骨，却能借由当代的设计重获新生。上海博物馆联合多方设计团队，将展厅中清代文人的精神世界，凝练为四款兼具日常实用与古典美学的限定文创。愿您在观展之余，亦能将这份“墨润浮生”的优雅带回日常生活。<img src=\"http://localhost:8080/files/640a519f-aebf-4d3b-8791-298d8711116e.png\"></p><h2>一、限定周边 · 免费领取攻略</h2><p>本板块周边为非卖品，需通过观展过程中的“文人体验”互动或特定票种福利获取。</p><h3>🦚 【笔底波澜】点翠美学 · 限定帆布袋</h3><ul><li><strong>美学蓝本</strong>：灵感源自上博馆藏《点翠镶嵌红蓝宝石如意簪》<strong>与河北博物馆藏</strong>《刺绣八仙过海图条屏》。</li><li><strong>设计巧思</strong>：大容量的原色厚质帆布袋上，将点翠那抹夺目的幽蓝与刺绣的五彩丝线，以高精度的数码泼墨工艺晕染开来。世俗的极致繁华在布料上“落尽”为抽象的山水波澜，高级且富有张力，是文艺出街的绝佳单品。</li><li><strong>获取方式【数字裂变打卡】</strong>：</li><li class=\"ql-indent-1\"><strong>浮生共鸣</strong>：在展厅内任选一处让您感触最深的文玩（如端砚或文具箱），拍照并分享至个人社交平台。</li><li class=\"ql-indent-1\"><strong>配文要求</strong>：带话题 <strong>#上博清代文人生活展#</strong> 并附上您对“繁华落尽，墨润浮生”的一句随笔感悟。</li><li class=\"ql-indent-1\"><strong>核销地点</strong>：一楼大堂服务中心（每人凭当日有效预约入馆码限领一个，每日限额，先到先得）。</li><li><strong>【特定票种与绿色通道】</strong>：</li><li class=\"ql-indent-1\"><strong>福利专享</strong>：凡持老年证、军官证、残疾证并预约<strong>社会福利票 / 老年票</strong>的观众，可在入馆时于绿色通道核验处，直接凭本人有效证件免任务免费领取一个，数量有限，先到先得。</li></ul><h2>二、：限定文创 · 倾心选购指南（案头清供）</h2><p>本板块周边为上海博物馆官方文创旗舰店、线上商城同步发售的清代文人生活美学重器。</p><p><br></p><h3>🧢 【金石骨气】汉隶张迁碑 · 刺绣棒球帽</h3><ul><li><strong>美学蓝本</strong>：视觉解构上海博物馆藏《清拓汉张迁碑册》。</li><li><strong>设计巧思</strong>：放弃了死板的全文印制，设计师仅截取了《张迁碑》中方整雄强、极具现代骨骼感的标志性汉隶笔触，以沉稳的黑白两色丝线，立体刺绣于复古棉质棒球帽上。低调、硬朗，戴上它，是将千年金石的傲骨顶在头上。</li><li><strong>获取方式：</strong>上海博物馆一楼【官方文宣旗舰店】/ 本站商城</li></ul><p><br></p><h3>🧥 【浮生墨白】清代山水 · 浮雕印花文化衫</h3><ul><li><strong>美学蓝本</strong>：融合广东省博物馆藏《清·端石千岩竞秀砚》的墨堂意境。</li><li><strong>设计巧思</strong>：选用高克重重装纯棉面料，通体呈现深邃的墨黑色与宣纸的米白色。胸前采用发泡浮雕工艺，将端砚上那幅“千岩竞秀”的重峦叠嶂以微立体的方式还原。摸上去如同砚石的肌理，穿在身上，便是将胸中的丘壑与山水化为了当代的时尚战袍。</li><li><strong>选购地点</strong>：上海博物馆一楼【官方文宣旗舰店】/ 本站商城。</li></ul><p><br></p><h3>🖋️ 【书斋自救】黑漆螺钿 · 限量笔记本钢笔组合</h3><ul><li><strong>美学蓝本</strong>：1:1 视觉解构河北博物馆藏《清·黑漆螺钿山水亭台纹文具箱》。</li><li><strong>设计巧思</strong>：这是本场大展的终极工艺文创。</li><li class=\"ql-indent-1\"><strong>笔记本</strong>：封面采用特殊钢琴烤漆材质，黑漆如夜，并在其上运用贝壳纸拼嵌出极为精细的螺钿山水亭台纹饰；</li><li class=\"ql-indent-1\"><strong>钢笔</strong>：笔身同样点缀螺钿流光，搭配定制的定制金尖，阻尼感完美复刻宣纸书写体验。</li><li class=\"ql-indent-1\">笔墨纸砚，在一开一合的礼盒间，为您在当代的办公桌上，筑起一方用来对抗浮躁、整理心绪的“微观避难所”。</li><li><strong>选购地点</strong>：上海博物馆一楼【官方文宣旗舰店】/ 本站商城。</li></ul><p><br></p><p><br></p><h2>⚠️ <span style=\"color: rgb(230, 0, 0);\">三、观展与周边领取核心守则</span></h2><p>为保障文物安全与高雅的观展秩序，请所有前来领取/购买周边的观众务必遵守：</p><p><br></p><ol><li><strong>时段对应核销</strong>：周边领取严格与您的预约场次挂钩。上午场（09:00 - 13:00）预约观众请勿在下午场前来排队领取，系统无法跨场次读取预约码。</li><li><strong>严格证件比对</strong>：由于【金石棒球帽】属于社会福利票/老年票觀眾的直接免打卡福利，现场将严格执行“人脸+身份证+物理证件（如残疾证、军官证等）”三合一比对，严禁代刷、冒用他人证件。</li><li><strong>退票熔断机制</strong>：如您在未检票前申请了线上退票，您的周边预约资格将同步注销。所有限定周边均为每日限量发放，如遇当日库存熔断，相关线上打卡活动将自动顺延至次日。</li><li><strong>守序即是高雅</strong>：文人书斋，重在静谧。在打卡拍照、排队或购买文化衫、笔记本的过程中，请勿大声喧哗、争抢。请听从馆方工作人员的现场指引，将您的脚步，放轻在清代文人的墨润时光里。</li></ol><p><br></p>', 11, '上海策展人', '巡展资讯', 0, '2026-05-25 21:49:40');

-- ----------------------------
-- Table structure for notice_type
-- ----------------------------
DROP TABLE IF EXISTS `notice_type`;
CREATE TABLE `notice_type`  (
  `type_id` bigint NOT NULL AUTO_INCREMENT,
  `type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '类型名称',
  `sort` int NULL DEFAULT 0,
  PRIMARY KEY (`type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '公告类型表' ROW_FORMAT = Dynamic;

