-- ----------------------------
-- Table structure for portal_banner
-- ----------------------------
DROP TABLE IF EXISTS `portal_banner`;
CREATE TABLE `portal_banner`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片地址',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标题文字',
  `sort` int NULL DEFAULT 0 COMMENT '排序（数字越小越靠前）',
  `status` tinyint NULL DEFAULT 1 COMMENT '0-隐藏 1-显示',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `main_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '基于Vue3的文物巡展管理系统' COMMENT '大标题',
  `link_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '点击跳转路径',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '门户轮播图' ROW_FORMAT = Dynamic;

