INSERT INTO `portal_banner` VALUES (3, 'http://localhost:8080/files/d5e27bac-20da-4fe2-91ae-3aa327d4d360.png', '于朱墙金瓦间，叩开历史之门；在毫端起落处，窥见古人风骨。', 0, 1, '2026-05-14 08:41:07', '《故宫翰墨》倾情奉献', 'http://localhost:5173/user/shop/detail?productId=3');

-- ----------------------------
-- Table structure for reservation
-- ----------------------------
DROP TABLE IF EXISTS `reservation`;
CREATE TABLE `reservation`  (
  `res_id` bigint NOT NULL AUTO_INCREMENT COMMENT '预约ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '预约人真实姓名',
  `id_card` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证件号码',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系邮箱',
  `exhibition_id` bigint NOT NULL COMMENT '巡展ID',
  `reserve_date` date NOT NULL COMMENT '预约参观日期',
  `status` tinyint NULL DEFAULT 0 COMMENT '预约状态: 0-已预约, 1-已核销/已参观, 2-已取消',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `time_slot` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '09:00-12:00' COMMENT '参观时段(如:上午场, 14:00-16:00)',
  `ticket_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '成人票' COMMENT '票种:成人,儿童,学生,老人,福利,其他',
  `verify_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '核销唯一加密串',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户备注',
  PRIMARY KEY (`res_id`) USING BTREE,
  UNIQUE INDEX `verify_code`(`verify_code` ASC) USING BTREE,
  INDEX `user_id`(`user_id` ASC) USING BTREE,
  INDEX `exhibition_id`(`exhibition_id` ASC) USING BTREE,
  CONSTRAINT `reservation_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `reservation_ibfk_2` FOREIGN KEY (`exhibition_id`) REFERENCES `exhibition_plan` (`exhibition_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2024024 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户预约管理表' ROW_FORMAT = Dynamic;

