-- ----------------------------
-- Table structure for shop_product
-- ----------------------------
DROP TABLE IF EXISTS `shop_product`;
CREATE TABLE `shop_product`  (
  `product_id` bigint NOT NULL AUTO_INCREMENT,
  `cat_id` bigint NULL DEFAULT NULL COMMENT '分类ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '商品描述',
  `price` decimal(10, 2) NOT NULL COMMENT '价格',
  `stock` int NULL DEFAULT 0 COMMENT '库存',
  `stock_warning` int NULL DEFAULT 10 COMMENT '库存预警阈值',
  `cover_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主图',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '图片列表(JSON数组)',
  `type` tinyint NULL DEFAULT 0 COMMENT '0-实体 1-虚拟',
  `status` tinyint NULL DEFAULT 1 COMMENT '0-下架 1-上架',
  `belong_museum` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属博物馆',
  `admin_id` bigint NOT NULL COMMENT '发布者ID',
  `sales` int NULL DEFAULT 0 COMMENT '销量',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `is_free_shipping` tinyint NULL DEFAULT 0 COMMENT '是否包邮 0-否 1-是',
  `has_shipping_insurance` tinyint NULL DEFAULT 0 COMMENT '是否含运费险 0-否 1-是',
  `shipping_fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '运费金额，0表示包邮',
  PRIMARY KEY (`product_id`) USING BTREE,
  INDEX `cat_id`(`cat_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商品表' ROW_FORMAT = Dynamic;

