INSERT INTO `shop_product` VALUES (5, 4, '测试文物商品', '<p>测试文物商品</p><p><strong>测试文物商品</strong></p><p><u>测试文物商品</u></p><h1>测试文物商品</h1><p><img src=\"http://localhost:8080/files/ac549aae-a017-4239-b237-ee5044b04202.png\"></p>', 30.00, 84, 10, 'http://localhost:8080/files/9f7843e8-4d0e-4d45-956a-c479d4fb8afd.png', NULL, 0, 0, '广东省博物馆', 6, 6, '2026-05-06 10:45:39', 0, 0, 12.00);
INSERT INTO `shop_product` VALUES (6, 4, '精美挂画', '<h1>🖼️ 【燕赵风骨·古今画卷】系列高端艺术微喷挂画</h1><blockquote><strong>把博物馆的惊艳，留给自家的墙壁。</strong></blockquote><blockquote>传世翰墨，落户寻常。我们精选本次“河北博物馆古今画卷展览”中备受瞩目的核心视觉，采用现代顶尖复刻工艺，将千百年前的墨色风骨与现代艺术的视觉张力，转化为点缀您家居空间的绝美雅器。</blockquote><h3>🎨 核心款式 · 艺术档案</h3><h3><strong>款式名称意境定位适合空间《千里江山·青绿华章》</strong>气势磅礴，开阔胸襟客厅背景墙、大堂、书房<strong>《歌乐图·宋韵丝竹》</strong>清雅内敛，富有市井烟火与宫廷雅趣茶室、餐厅、玄关<strong>《五四青年·觉醒时代》</strong>现代时尚，热血张扬，极具视觉冲击力艺术工作室、现代极简客厅、书房<strong>《水墨老人·岁月沉淀》</strong>禅意留白，写意人生，尽显东方智慧禅修室、茶空间、长辈房🔍 匠心工艺 · 硬核科普</h3><p>为了完美还原原作的气韵，我们拒绝流水线式的粗糙印刷，死磕每一个工艺细节：</p><ul><li><strong>12色超高清艺术微喷（Giclée）</strong></li><li>采用专业级艺术微喷技术，色彩馆藏级还原。无论是《千里江山》中孔雀石与蓝铜矿的<strong>层层敷色</strong>，还是水墨老人中“墨分五色”的干湿浓淡，均能纤毫毕现，直逼原作神韵。</li><li><strong>精选特级宣纸/高档棉质油画布</strong></li><li>根据画作风格定制材质。古风系列采用<strong>抗噪、防霉的特制宣纸纹理纸</strong>，保留宣纸独有的洇散感；现代艺术系列采用<strong>高密度防水油画布</strong>，肌理感强，色彩饱满。</li><li><strong>环保矿物墨水 · 百年不褪色</strong></li><li>使用纯天然、无毒无味的环保矿物墨水。防紫外线、耐光照，真正做到“白青相映，历久弥新”，可传家、可收藏。</li><li><strong>高端实木画框 · 匠心榫卯</strong></li><li>选用进口黑胡桃木/水曲柳实木画框，经多道手工打磨抛光，线条硬朗。采用传统<strong>榫卯结构</strong>固定，严丝合缝，久用不易变形。</li></ul><h3>📐 商品规格参数</h3><ul><li><strong>画芯材质</strong>：特级艺术宣纸纸本 / 哑光高质感油画布</li><li><strong>外框材质</strong>：黑胡桃木色实木框 / 哑光现代黑铝合金框</li><li><strong>工艺类型</strong>：馆藏级艺术微喷（配3mm高透防眩光有机玻璃）</li><li><strong>常用尺寸</strong>（支持私信定制）：</li><li class=\"ql-indent-1\"><strong>横幅长卷</strong>：$120\\text{cm} \\times 45\\text{cm}$ / $150\\text{cm} \\times 55\\text{cm}$（完美还原长卷气象）</li><li class=\"ql-indent-1\"><strong>竖幅方版</strong>：$50\\text{cm} \\times 70\\text{cm}$ / $60\\text{cm} \\times 90\\text{cm}$</li><li><strong>包装附件</strong>：品牌专属礼盒、定制防跌落无痕钉、水平仪、纯棉白手套。</li></ul><h3>🏠 场景秀：一幅好画，如何改变一个家？</h3><blockquote><strong>“计白当黑，虚实相生。”</strong></blockquote><ul><li><strong>客厅 · 撑起家的气度</strong>：一幅《千里江山》，连绵的青绿山水在沙发后延展，不仅是视觉焦点，更是主人胸怀与审美品味的无声宣告。</li><li><strong>书房 · 独享一室清幽</strong>：挂一幅《水墨老人》或赵佶草书，展卷迎风，一盏清茶。在疾风劲草般的线条里，找回内心的宁静与笃定。</li><li><strong>玄关 · 开门见喜的惊艳</strong>：现代红蓝撞色的《五四青年》，让每一个推门而入的客人，瞬间感受到现代艺术的张力与扑面而来的朝气。</li></ul><h3>📦 购物保障与物流</h3><ul><li><strong>顺丰包邮</strong>：全产业链顺丰加固木架包装，确保艺术品完好无损送达您的手中。</li><li><strong>破损包退</strong>：物流途中若有任何磕碰损坏，请在签收24小时内联系客服，我们将免费为您重新顺丰补发。</li></ul><blockquote><strong>限时福利</strong>：</blockquote><blockquote>凡本次“河北博物馆巡展”期间在线上或展会现场下单的观众，均可获赠<strong>展览官方限量版纪念画册一本</strong>及<strong>文创书签一枚</strong>。数量有限，赠完即止。</blockquote><p><br></p>', 20.00, 95, 10, 'http://localhost:8080/files/9ee64a21-f375-4f96-adac-2d392cbdea44.png', NULL, 0, 1, '河北博物馆', 3, 4, '2026-05-06 12:15:58', 0, 0, 10.00);
INSERT INTO `shop_product` VALUES (7, 1, '【广博×故宫联名】故宫翰墨', '<h2>🌟 【广博×故宫联名】故宫翰墨 —— 双城璧合，尽显中华文脉之美</h2><p>当岭南文化窗口「广东省博物馆」<strong>与</strong>六百年皇家美学「故宫博物院」破壁相遇，一场跨越地理限制的南北文化碰撞交融于此。</p><p>「故宫翰墨」联名系列商品，将故宫馆藏的绝美书画珍玩，与广东省博物馆所承载的地域文化、文雅生活美学精妙结合。它不仅是一件商品，更是一部可以握在手中、摆在案头的“流动的博物馆展厅”。</p><h3>🎨 核心亮点与文化内涵</h3><ul><li><strong>双馆正版背书，文化含金量“天花板”</strong></li><li>由广东省博物馆与故宫文创联合打造，设计灵感源自两馆珍藏的国宝级书画、墨宝及宫廷纹样。南北文化交相辉映，正统且极具收藏价值。</li><li><strong>南北美学碰撞，雅致超脱</strong></li><li>既有故宫海纳百川的皇家大气、厚重翰墨，又融入了广博海丝文化、岭南文脉的精致与细腻。将传统的“琴棋书画诗酒茶”现代生活化，尽显文人雅趣。</li><li><strong>匠心工艺还原，细节处见真章</strong></li><li>产品采用高精度印刷与考究的材质工艺（如浮雕、烫金、丝绸质感等），近乎完美地还原了古代书画的墨韵与色彩，让千年文脉触手可及。</li><li><strong>兼具实用与格调，送礼典藏皆宜</strong></li><li>该系列涵盖了文房雅玩、生活美学用品等。无论是摆在书房彰显品味，还是作为一份沉甸甸的文化礼品赠送给导师、藏友、贵客，都极具文化分量。</li></ul><h3>🏛️ 「双城故事」设计元素</h3><p><strong>灵感来源文化意象产品视觉呈现故宫·皇家翰墨</strong>馆藏历代名家书画真迹、帝王墨宝。苍劲磅礴的笔触、经典的宫廷配色，彰显正统大气。<strong>广博·岭南文脉</strong>粤地文人墨客的诗雅情怀、岭南特色藏品元素。细腻婉约的纹理、内敛的东方韵味，平添一分灵动。</p><h3>💡 为什么值得拥有？</h3><blockquote>“从紫禁城到岭南，跨越千里的文化共鸣，都在这一笔一墨之间。”</blockquote><p>「故宫翰墨」系列不仅仅是一件文创，它承载的是两大博物馆对中华优秀传统文化的守护与活化。它打破了文物的冰冷玻璃罩，让那些在历史长河中熠熠生辉的墨迹与审美，真正走入你的日常生活。</p><p><strong>手触双馆匠心，落墨中华意境。</strong></p><p>👉 <em>立即将这份跨越时空的“博物馆级”浪漫带回家！</em></p>', 50.00, 99, 10, 'http://localhost:8080/files/3b0ba580-cc33-48a8-9b7d-c99c8bd0f500.png', NULL, 0, 1, '广东省博物馆', 6, 1, '2026-05-25 17:46:06', 1, 1, 0.00);
INSERT INTO `shop_product` VALUES (8, 9, '\"清代山水 · 浮雕印花\"主题文化衫', '<h1> 上海博物馆特献 ·【浮生墨白】清代山水浮雕印花文化衫</h1><blockquote><strong>设计自白</strong>： 物质的繁华终会散去，但胸中的山水永远挺拔。本款文化衫以广东省博物馆藏国家级珍贵文物——**《清 · 端石千岩竞秀砚》**为灵感源泉。设计师打破了传统文物文创只是“平面复印”的敷衍手法，将清代文人最核心的精神图腾——“案头清供的山水丘壑”，通过当代重装纺织与微浮雕工艺，转化为一件可以穿在身上的“文人战袍”。</blockquote><h2><img src=\"http://localhost:8080/files/b6a5d4d9-e683-495c-ab68-f6c2e68d4bdb.png\"></h2><h2> </h2><h2>核心设计美学解构</h2><p><br></p><p>		这件文化衫不只是一件衣物，更是将清代文人的风骨与宿命，穿在身上的美学宣言。衣服胸前摒弃了敷衍的普通胶印，重金采用<strong>立体发泡浮雕工艺</strong>，将广东省博物馆藏“清端石千岩竞秀砚”上那幅重峦叠嶂、古木幽深的宏大山水，以微观立体的形式于布料上重塑。当指墨相发，你的指尖抚摸上去，能清晰地感受到如同古代老坑端砚般斑驳、凹凸有致的细腻石质肌理——纵使外界风雨大作、世俗喧嚣，而你胸中自有一派不畏风霜的苍翠山水。</p><p>		在色彩的克制上，衣服融入了<strong>极简主义的墨白双色</strong>：<strong>“墨黑”取自古墨研磨入宣纸时的深邃，绝非市面上普通的死黑，而是带着历史厚重感与文人内敛气质的隐逸焦墨；“纸白”则取自天然生宣历经岁月洗礼后的微微米白，温润、不刺眼，如同清晨书斋窗棂里折射出的一缕晨光。更有极为考究的金石微章</strong>隐藏于衣服后颈处，低调刺绣着一枚复刻自清代文人藏书印的“墨润”小方印。</p><p>		提笔执墨，落暮皆情。后人视之，唯见背影，便已读懂你骨子里那份不随波逐流的文人风雅。</p><h2><br></h2><h2>匠心版型与面料工艺</h2><p>为了承载这份文化的厚度，我们在面料的编织和剪裁上同样追求清代手工业巅峰时的执着：</p><p><br></p><p><strong>260g 双纱精梳纯棉</strong>： 精选长绒棉，260克重磅厚质面料。上身挺括有型，绝不松垮塌陷。它就像文人的骨气一样，历经多次洗涤依然挺拔，自带一种高阶的“重装质感”。</p><p><img src=\"http://localhost:8080/files/3aa5f1dd-4695-4a45-b9c0-806de0c2410e.png\"></p><p><strong>液氨食毛工艺</strong>： 面料表面经过液氨整理与微食毛技术，去除了所有多余的棉毛屑。衣服表面带有如同顶级绢素和温润端砚般的淡淡微光，触感亲肤细腻，吸汗透气。</p><p><img src=\"http://localhost:8080/files/328ff851-5876-426e-8a80-af3360553010.png\"></p><ul><li><strong>【文人廓形】海派宽松剪裁</strong>： 采用上博标志性的海派落肩微宽松版型。不挑身材，包容度极高。无论是日常办公作为内搭，还是周末出行文艺出街，都能穿出一种落落大方、松弛随性的文人风度。</li></ul><h2><br></h2><h2> 商品基础规格参数</h2><ul><li><strong>产品名称</strong>：【繁华落尽·墨润浮生】清代山水浮雕印花文化衫</li><li><strong>面料成分</strong>：100% 精梳纯棉（重磅260g）</li><li><strong>工艺类型</strong>：三维立体发泡浮雕、重工防变形领条、高精数码活性印染</li><li><strong>可选颜色</strong>：焦墨黑 / 宣纸白</li><li><strong>尺码推荐</strong>：S / M / L / XL / XXL（海派宽松版型，男女同款）</li><li><strong>洗涤建议</strong>：为保护胸前珍贵的浮雕山水肌理，建议反面手洗或装入洗衣袋后轻柔机洗，请勿暴晒。</li></ul><p><br></p>', 1.01, 166, 10, 'http://localhost:8080/files/5c480034-eca8-4f56-aea6-eeb40f8843b6.png', NULL, 0, 1, '上海博物馆', 10, 4, '2026-05-25 22:02:59', 0, 0, 15.00);
INSERT INTO `shop_product` VALUES (9, 9, '金石文化棒球帽', '<h3>上海博物馆特献 ·【金石骨气】汉隶张迁碑刺绣棒球帽</h3><p>设计自白： 文人的骨气，从不流于表面，而是刻进骨血、顶在头上的傲然。本款限定棒球帽以展厅中的金石重器——上海博物馆藏《清拓汉张迁碑册》为美学蓝本。设计师打破了传统文创只是死板复印文字的套路，截取了汉隶中最具现代骨骼感的标志性笔触，将跨越千年的金石风骨，转化为当代街头最硬朗的时尚符号。</p><p><img src=\"http://localhost:8080/files/d300ee1c-d3bf-4073-8baa-9cb35dda84f1.png\"></p><p>一、 核心设计美学解构</p><p><br></p><ol><li>【方整雄强】张迁碑汉隶重工刺绣 放弃了冗长的全文印制，设计师在帽子正面仅精选了《张迁碑》中方整质朴、欹侧中有千钧之力的汉隶笔画局部。采用高密度日本田岛绣花工艺，以沉稳的黑白两色丝线，在帽身进行多层叠加上色。笔画的转折处斩钉截铁，横平竖直间带有如刀劈斧凿般的微立体肌理。摸上去是宣纸拓片般的凹凸质感，戴上它，是将千年金石的傲骨与不向流俗低头的骨气，真正顶在头上。</li><li>【岁月的墨痕】复古做旧色系</li></ol><ul><li>碑石黑：还原汉代碑石历经千年的沧桑与深邃，沉稳而冷峻。</li><li>拓片白：取自高质感拓片宣纸的天然米白，纯粹而不张扬。 两款配色皆自带一种复古的洗水做旧质感，恰似一块行走的活字碑刻，极具时间分量。</li></ul><ol><li>【一印永留】后调带金石微章 隐藏细节：帽后可调节扣带处，低调刺绣有一枚复刻自清代文人藏书印的“墨润”小方印。当您留下背影，这枚象征风雅的朱砂红印，便是对您独特文人身份的审美盖签。</li></ol><p>二、 匠心版型与面料工艺</p><p>为了配得上金石的硬朗，我们在帽子的版型与面料上同样追求极致：</p><p><br></p><ul><li>【重装风骨】16安重磅硬挺水洗纯棉帆布： 精选高密度重磅帆布面料，经过特殊的文人洗水工艺处理，触感扎实、不易变形。像文人的脊梁一样，历经风雨摩擦，依然保持硬挺的廓形。</li><li>【海派修颜】亚洲定制版硬顶帽型： 前片采用高规格的硬顶定型结构，深度契合亚洲人头型设计。视觉上具有极佳的显脸小效果，拉长面部线条，无论正戴还是反戴，都能穿出一种松弛随性却不失锋芒的文人风度。</li><li>【清爽书斋】六孔透气与吸汗带圈： 帽身分布六个重工绣花透气孔，内里搭配纯棉高弹吸汗带，吸湿排汗。即使在炎炎夏日出行，也能让你的头部如置身清幽书斋般，时刻保持冷静与舒适。</li><li><img src=\"http://localhost:8080/files/df835983-bcae-46de-ba1a-2dbac8512fb5.png\"></li></ul><p>三、 商品基础规格参数</p><p><br></p><ul><li>产品名称：【繁华落尽·墨润浮生】汉隶张迁碑刺绣棒球帽</li><li>面料成分：100% 重磅水洗棉（16安帆布）</li><li>工艺类型：高密度3D金石刺绣、金属调节扣（后带可调）</li><li>可选颜色：碑石黑 / 拓片白</li><li>尺码推荐：均码（头围 54cm-60cm 可自由调节，男女同款）</li><li>洗涤建议：为保护前片硬顶版型及珍贵的金石刺绣，建议局部沾水手洗，切勿直接丢进洗衣机绞洗。</li></ul><p><br></p>', 0.00, 219, 10, 'http://localhost:8080/files/b0243644-cba9-4aa1-b784-55eb7a6fde3f.png', NULL, 0, 1, '上海博物馆', 10, 1, '2026-05-25 22:09:19', 1, 0, 0.00);

-- ----------------------------
