-- ----------------------------
-- View structure for view_exhibitor_reservation
-- ----------------------------
DROP VIEW IF EXISTS `view_exhibitor_reservation`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_exhibitor_reservation` AS select `r`.`res_id` AS `res_id`,`r`.`user_id` AS `visitor_user_id`,`r`.`real_name` AS `real_name`,`r`.`id_card` AS `id_card`,`r`.`phone` AS `phone`,`r`.`email` AS `email`,`r`.`reserve_date` AS `reserve_date`,`r`.`status` AS `status`,`r`.`time_slot` AS `time_slot`,`r`.`ticket_type` AS `ticket_type`,`r`.`verify_code` AS `verify_code`,`r`.`remark` AS `remark`,`r`.`create_time` AS `create_time`,`ep`.`exhibition_id` AS `exhibition_id`,`ep`.`title` AS `exhibition_title`,`u`.`user_id` AS `exhibitor_user_id`,`u`.`belong` AS `museum_name` from (((`reservation` `r` join `exhibition_plan` `ep` on((`r`.`exhibition_id` = `ep`.`exhibition_id`))) join `exhibition_application` `ea` on((`ep`.`app_id` = `ea`.`app_id`))) join `sys_user` `u` on((`ea`.`applicant_id` = `u`.`user_id`)));

SET FOREIGN_KEY_CHECKS = 1;
